function accChips(a){return a.map(k=>`<span class="chip">${ico(ACCI[k])} ${ACC[k]}</span>`).join('')}
function card(j){
 const sv=S.saved.includes(j.id);
 const label=`${j.t}, ${j.co}${j.v?' บริษัทยืนยันแล้ว':''}, คะแนน ${j.r} จาก 5, ${j.n} รีวิว${j.acc.length?', รองรับ '+j.acc.map(k=>ACC[k]).join(' '):''}${j.match?', ทักษะตรง '+j.match+' เปอร์เซ็นต์':''}, ${j.pay}`;
 return `<article class="card"><div class="cv" aria-hidden="true">${slides(j)}</div>
 <button class="heart" data-save="${j.id}" aria-pressed="${sv}" aria-label="${sv?'เลิกบันทึก':'บันทึก'}งาน ${esc(j.t)}">${sv?'♥':'♡'}</button>
 <div class="cb"><div class="mh"><span class="av" style="background:var(${j.c})" aria-hidden="true">${j.ini}</span>${j.co}${j.v?' <span class="chip g">✓ ยืนยันแล้ว</span>':''}</div>
 <h3 class="ttl"><a href="#job-${j.id}" aria-label="${esc(label)}">${j.t}</a></h3>
 <div class="meta"><b>★ ${j.r}</b> (${j.n} รีวิว) · ${j.type} · ${j.mode}</div>
 <div class="chips" style="margin:6px 0"><span class="chip lvc" title="จำลองเพื่อการสาธิต"><i class="dotp"></i><b data-lv="${j.id}">${LV[j.id]||5}</b> กำลังดู</span>${j.urgent?'<span class="chip o">⚡ ด่วน</span>':''}${j.acc.length?'<span class="chip"><i class="ico ic-access" aria-hidden="true"></i> รองรับ</span>':''}${j.match?`<span class="chip g">ตรง ${j.match}%</span>`:''}${j.potential?'<span class="chip p">🌱 ศักยภาพ</span>':''}</div>
 <div class="ft"><span class="meta">ปิดรับ ${j.close}</span><span class="price">${j.pay}</span></div></div></article>`}
function gigCard(g){return `<article class="card"><div class="cv" aria-hidden="true">${slides(g)}</div><div class="cb"><div class="mh"><span class="av" style="background:var(${g.c});border-radius:50%" aria-hidden="true">${g.ini}</span>${g.who}</div><h3 class="ttl"><a href="#gig-${g.id}">${g.t}</a></h3><div class="meta"><b>★ ${g.r}</b> (${g.n}) · ขายแล้ว ${g.n*3}</div><div class="ft"><span class="chip g">🛡 ระบบกลาง</span><span class="price">เริ่มต้น ฿${g.pk[0][1].toLocaleString()}</span></div></div></article>`}
function progCard(p){return `<article class="box prog-card" style="background:var(${p[5]})"><span class="sample">ตัวอย่าง</span><span class="cic" aria-hidden="true">${ico(EI[p[0]]||'spark')}</span><h3 style="font-size:1rem">${p[1]}</h3><p class="meta" style="margin:4px 0">${p[2]}</p><div class="chips"><span class="chip">⏱ ${p[3]}</span>${p[4].map(x=>`<span class="chip g">${x}</span>`).join('')}</div></article>`}

const V={};
V.home=()=>`<section class="hero herox"><span class="fl f1">${ico('flask')}</span><span class="fl f2">${ico('chart')}</span><span class="fl f3">${ico('palette')}</span><span class="fl f4">${ico('laptop')}</span><span class="fl f5">${ico('mega')}</span>
 <div style="flex:1;min-width:0;position:relative;z-index:1"><span class="kick">${ico('spark')} งานแรก · ฝึกงาน · พาร์ทไทม์</span> <span class="kick livek" title="ตัวเลขจำลองเพื่อการสาธิต"><i class="dotp"></i><b id="liveTot">${Object.values(LV).reduce((a,b)=>a+b,0)}</b> คนกำลังดูงานอยู่ตอนนี้</span><h1>ก่อนไปทำงาน <span class="shine">มาดูก่อน</span></h1><p>ฝึกงาน งานแรก พาร์ทไทม์ — พร้อมรีวิวจริงจากคนเคยทำ</p>
 <form class="hsearch h3f" id="heroSearch" role="search"><label class="sr" for="heroQ">ตำแหน่ง ทักษะ หรือบริษัท</label><span class="si">${ico('search')}<input id="heroQ" placeholder="ลอง “ฝึกงาน QC”" data-rot></span><span class="si lc">${ico('pin')}<input id="heroLoc" list="locs" placeholder="ทำเล / BTS" aria-label="สถานที่ทำงาน"></span><button>ค้นหางาน</button></form>
 <div class="tags">${['ฝึกงาน QC','Data','Graphic','บาริสต้า','Remote'].map(t=>`<button data-q="${t}">${t}</button>`).join('')}<button data-go="inclusive"><i class="ico ic-access" aria-hidden="true"></i> รองรับคนพิการ</button></div></div><img class="mascot" src="data:image/png;base64," alt=""></section>
 <div class="trust" role="list">${[['✓','บริษัทยืนยันตัวตน'],['★','รีวิวจากคนเคยทำจริง'],['⏱','ตามใบสมัครให้ใน 14 วัน'],['🛡','ฟรีแลนซ์จ่ายผ่านระบบกลาง'],['<i class="ico ic-access" aria-hidden="true"></i>','ใช้กับโปรแกรมอ่านจอได้']].map(x=>`<div role="listitem"><b aria-hidden="true">${x[0]}</b> ${x[1]}</div>`).join('')}</div>
 <h2 class="sr">หมวดงาน</h2><div class="cats">${CATS.map(c=>`<button data-cat="${c[2]}"><span class="cic big" style="background:var(--c${(CATS.indexOf(c)%6)+1})" aria-hidden="true">${ico(CI[c[2]])}</span>${c[1]}</button>`).join('')}</div>
 <div class="sec"><h2>งานแนะนำสำหรับคุณ</h2><a href="#jobs">ดูทั้งหมด ›</a></div><div class="grid">${JOBS.slice(0,4).map(card).join('')}</div>
 <div class="sec"><h2>ฟรีแลนซ์จากนักศึกษา</h2><a href="#gigs">ดูทั้งหมด ›</a></div><div class="grid">${GIGS.map(gigCard).join('')}</div>
 <div class="sec"><h2>ทดลองทำงานจริง 1–4 สัปดาห์</h2><a href="#programs">ดูโครงการ ›</a></div><div class="grid">${PROGRAMS.map(progCard).join('')}</div>`;
const FAST=[1,2,4,6,8];const mon=j=>j.payN*(/\/วัน/.test(j.pay)?22:1);
function filtered(){const f=S.f;let r=JOBS.filter(j=>{
 if(f.loc&&!j.loc.toLowerCase().includes(f.loc.toLowerCase()))return false;if(f.minPay&&mon(j)<f.minPay)return false;if(f.fast&&!FAST.includes(j.id))return false;
 if(f.q){const q=f.q.toLowerCase();if(!(j.t+j.co+j.skills.map(s=>s[0]).join(' ')+j.type).toLowerCase().includes(q))return false}
 if(f.types.length&&!f.types.includes(j.type))return false;if(f.modes.length&&!f.modes.includes(j.mode))return false;
 if(f.acc.length&&!f.acc.every(a=>j.acc.includes(a)))return false;if(f.verified&&!j.v)return false;
 if(f.cat){if(f.cat==='remote'){if(j.mode!=='Remote'&&!j.acc.includes('remote'))return false}else if(f.cat==='acc'){if(!j.acc.length)return false}else if(j.cat!==f.cat)return false}
 return true});
 const so={match:(a,b)=>(b.match||0)-(a.match||0),new:(a,b)=>a.days-b.days,pay:(a,b)=>b.payN-a.payN,rate:(a,b)=>b.r-a.r};r.sort(so[f.sort]);return r}
function cb(group,val,label,checked){return `<label><input type="checkbox" data-f="${group}" value="${val}" ${checked?'checked':''}> ${label}</label>`}
V.jobs=(incl)=>{const f=S.f;const r=filtered();const chips=[...f.types,...f.modes,...f.acc.map(a=>ACC[a]),...(f.verified?['บริษัทยืนยันแล้ว']:[]),...(f.q?['“'+f.q+'”']:[]),...(f.cat?[CATS.find(c=>c[2]===f.cat)[1]]:[])];
 return `${incl?`<section class="hero" style="margin-bottom:16px"><div style="flex:1"><h1><i class="ico ic-access" aria-hidden="true"></i> งานที่รองรับคนพิการ</h1><p>ค้นจาก “สิ่งที่ช่วยให้คุณทำงานได้ดี” ไม่ต้องบอกประเภทความพิการ · บริษัทที่จ้างตามมาตรา 33 หรือใช้มาตรา 35 ลงประกาศได้</p></div></section>`:''}
 <div class="layout"><details class="ffold" ${innerWidth>860||S.fsOpen?'open':''}><summary>ตัวกรอง (${chips.length})</summary><aside class="side" aria-label="ตัวกรอง"><div class="fhead shonly"><b>ตัวกรอง</b><button type="button" class="fx" data-closefilter aria-label="ปิดตัวกรอง">✕</button></div>
 <fieldset><legend>ประเภทงาน</legend>${['ฝึกงาน','งานประจำ','พาร์ทไทม์'].map(t=>cb('types',t,t,f.types.includes(t))).join('')}</fieldset>
 <fieldset><legend>รูปแบบงาน</legend>${['Onsite','Hybrid','Remote'].map(t=>cb('modes',t,t,f.modes.includes(t))).join('')}</fieldset>
 <fieldset><legend>ความน่าเชื่อถือ</legend><label><input type="checkbox" data-f="verified" ${f.verified?'checked':''}> บริษัทยืนยันแล้ว</label></fieldset>
 <fieldset><legend>ค่าตอบแทนขั้นต่ำ <b id="payV">${f.minPay?'฿'+f.minPay.toLocaleString():'ทั้งหมด'}</b></legend><input type="range" class="range" min="0" max="25000" step="500" value="${f.minPay||0}" data-pay aria-label="ค่าตอบแทนขั้นต่ำต่อเดือน"></fieldset>
 <fieldset><legend>การตอบกลับ</legend><label><input type="checkbox" data-ff="fast" ${f.fast?'checked':''}> บริษัทตอบเร็ว (ภายใน 3 วัน)</label></fieldset>
 <fieldset class="accbox"><legend><i class="ico ic-access" aria-hidden="true"></i> การรองรับในที่ทำงาน</legend>${Object.keys(ACC).map(k=>cb('acc',k,ACC[k],f.acc.includes(k))).join('')}</fieldset>
 <button class="btn" id="clearF">ล้างตัวกรอง</button><button type="button" class="btn y shonly" data-closefilter>ดูผลลัพธ์ (${r.length})</button></aside></details>
 <section aria-labelledby="resH"><form id="jobSearch" role="search" class="hsearch" style="height:44px;margin-bottom:12px;box-shadow:none;border:1.5px solid var(--line)"><input id="jobQ" aria-label="ค้นหางาน" placeholder="ตำแหน่ง ทักษะ หรือบริษัท" value="${esc(f.q)}"><span class="locw dk"><i class="ico ic-pin" aria-hidden="true"></i><input id="jobLoc" list="locs" placeholder="ทำเล / BTS" aria-label="สถานที่" value="${esc(f.loc||'')}"></span><button>ค้นหา</button></form><div class="bar3"><h2 id="resH" style="font-size:1.15rem">พบ ${r.length} งาน</h2>${chips.map(c=>`<span class="chip">${esc(c)}</span>`).join('')}<span style="flex:1"></span><label for="sortSel" class="meta">เรียง</label><select id="sortSel">${[['match','แนะนำ (ทักษะตรง)'],['new','ใหม่สุด'],['pay','ค่าตอบแทนสูง'],['rate','คะแนนบริษัท']].map(o=>`<option value="${o[0]}" ${f.sort===o[0]?'selected':''}>${o[1]}</option>`).join('')}</select></div>
 ${r.length?`<div class="grid g3">${r.map(card).join('')}</div>`:`<div class="box empty">ยังไม่มีงานที่ตรงทุกเงื่อนไข ลองเอาตัวกรองบางข้อออก</div>`}
 <p class="notice" style="margin-top:14px">คะแนน “ตรง %” ช่วยเรียงงาน ไม่ได้ใช้ตัดใครออก และไม่ใช้อายุ เพศ หรือความพิการในการคำนวณ</p></section></div>`};
const ACCD={ramp:'ทางลาด ลิฟต์ ห้องน้ำและโต๊ะทำงานที่เข้าถึงได้',sr:'ใช้โปรแกรมอ่านจอ/ขยายจอได้ในงานจริง',sign:'มีล่ามภาษามือ หรือคำบรรยายในการประชุม',remote:'ทำงานที่บ้านได้ ไม่ต้องเดินทางไกล',flex:'ปรับเวลาเข้า-ออกงานและนัดพบแพทย์ได้',m33:'บริษัทรับคนพิการตามมาตรา 33'};
V.inclusive=()=>{const h=V.jobs(true);const i=h.indexOf('<div class="layout">');
 const intro=`<div class="sec"><h2>เลือกสิ่งที่ต้องการในที่ทำงาน</h2><span class="meta">กดเพื่อกรองงาน</span></div><div class="accgrid">${Object.keys(ACC).map(k=>`<button class="accc" data-accf="${k}" aria-pressed="${S.f.acc.includes(k)}"><span class="cic big">${ico(ACCI[k])}</span><b>${ACC[k]}</b><small>${ACCD[k]}</small></button>`).join('')}</div><div class="box" style="margin:14px 0;background:var(--green-tint)"><b style="color:var(--green)">${ico('shield')} บริษัทต้องระบุการรองรับจริง</b><p style="margin:4px 0 0;font-size:.88rem">ทุกข้อมูลมาจากบริษัทและถูกยืนยันด้วยรีวิวจากคนเคยทำงาน หากไม่ตรงความจริง ผู้ใช้กดรายงานได้</p></div>`;
 return h.slice(0,i)+intro+h.slice(i)};
V.job=id=>{const j=job(id);if(!j)return V.home();const applied=S.apps.find(a=>a.job===j.id&&a.status!=='withdrawn');
 return `<p class="meta"><a href="#jobs">หางาน</a> › ${j.type}</p><div class="detail"><div class="col"><h1 style="font-size:1.6rem">${j.t}</h1>${j.type==='ฝึกงาน'?`<div class="box certban">${ico('doc')} <span><b>ได้รับใบรับรองการฝึกงาน</b> เมื่อฝึกครบ ออกโดย Maadoo Job พร้อมผลประเมินจากพี่เลี้ยง ใช้ยืนยันกับมหาวิทยาลัยได้</span></div>`:''}
 ${gallery(j,'ภาพจริงจากบริษัทและรีวิวจะแสดงที่นี่')}
 <div class="box stats"><span class="av" style="background:var(${j.c});width:52px;height:52px;font-size:1rem" aria-hidden="true">${j.ini}</span><div style="flex:1;min-width:160px"><b style="color:var(--ink)">${j.co}</b> ${j.v?'<span class="chip g">✓ บริษัทยืนยันแล้ว</span>':'<span class="chip o">ยังไม่ยืนยันบริษัท</span>'}<div class="meta">★ ${j.r} จาก ${j.n} รีวิว</div></div><div class="stat"><b>96%</b><span>ตอบใบสมัคร</span></div><div class="stat"><b>4 วัน</b><span>ตอบเฉลี่ย</span></div><div class="stat"><b>62%</b><span>อยู่ยาว</span></div></div>
 <div class="two"><div class="box"><h2 style="font-size:1rem">ทำอะไรบ้าง</h2><ul class="list">${j.duty.map(d=>`<li>${d}</li>`).join('')}</ul><h2 style="font-size:1rem;margin-top:8px">สวัสดิการ</h2><p style="margin:2px 0">${j.ben}</p></div>
 <div class="box"><h2 style="font-size:1rem">ขั้นตอนหลังสมัคร</h2><ol class="list"><li>ส่งใบสมัคร</li><li>บริษัทเปิดดู · เงียบ 3 วัน เราเตือนให้</li><li>เลือกเวลาสัมภาษณ์ในแอป</li><li>แจ้งผลในแอป ภายใน 14 วัน</li></ol></div></div>
 <div class="box" style="border:2px solid var(--blue)"><h2 style="font-size:1rem"><i class="ico ic-access" aria-hidden="true"></i> การรองรับในที่ทำงาน</h2>${j.acc.length?`<div class="chips" style="margin-top:6px">${accChips(j.acc)}</div><p class="meta" style="margin:6px 0 0">บริษัทระบุ · ขอการปรับเพิ่มได้ตอนสมัคร</p>`:`<p class="meta" style="margin:4px 0 0">บริษัทยังไม่ระบุ · ถามผู้ประสานงานได้ตอนสมัคร</p>`}</div>
 <div class="box"><h2 style="font-size:1rem">ทักษะที่งานนี้ต้องการ</h2><ul class="list">${j.skills.map(s=>`<li>${s[1]?'✅':'⚪'} ${s[0]} ${s[1]?'· คุณมีแล้ว':'· ยังไม่มี'}</li>`).join('')}</ul>${j.potential?'<p><span class="chip p">🌱 มีศักยภาพพัฒนาต่อได้</span> ลองคอร์สหรือทดลองทำงานจริงเพื่อปิดช่องว่าง</p>':''}</div>
 <div class="box"><h2 style="font-size:1rem">รีวิวจากคนเคยทำ</h2>${[['บรรยากาศ',4.4],['พี่เลี้ยง/หัวหน้า',4.3],['การเข้าถึง',j.acc.length?4.2:3.5]].map(x=>`<div class="rbar"><span style="width:110px">${x[0]}</span><span class="tr"><i style="width:${x[1]*20}%"></i></span><b>${x[1]}</b></div>`).join('')}<p style="margin:8px 0 0">“${j.q}” <span class="meta">· ยืนยันตัวตนแล้ว</span></p></div></div>
 <aside class="sticky" aria-label="สมัครงาน"><div class="box pricebox"><div class="meta">ค่าตอบแทน</div><div class="big">${j.pay}</div><p class="meta" style="margin:4px 0 10px">📍 ${j.loc}<br>🏢 ${j.mode} · ${j.type} · ⏳ ปิดรับ ${j.close}</p>
 ${j.match?`<div style="display:flex;gap:10px;align-items:center;background:var(--tint);border-radius:14px;padding:8px">${ring(j.match,j.potential?'var(--purple)':'var(--green)')}<div class="meta">ทักษะตรง ${j.match}%<br>${j.potential?'🌱 มีศักยภาพพัฒนาต่อได้':'ทักษะจำเป็นตรงเกือบครบ'}</div></div>`:''}
 <button class="btn b full aib" style="margin-top:12px" data-aicheck="${j.id}">${ico('spark')} ให้ AI ตรวจว่าเหมาะกับฉันไหม</button>
 <button class="btn y full" style="margin-top:8px" data-apply="${j.id}" ${applied?'disabled':''}>${applied?'สมัครแล้ว ✓':'สมัครงานนี้ · ใช้ 1 จาก '+S.slotLimit+' Slot'}</button>
 <div style="display:flex;gap:8px;margin-top:8px"><button class="btn" style="flex:1" data-save="${j.id}" aria-pressed="${S.saved.includes(j.id)}">${S.saved.includes(j.id)?'♥ บันทึกแล้ว':'♡ บันทึก'}</button><button class="btn" style="flex:1" data-share="${j.id}">แชร์ไป LINE</button></div></div>
 <div class="box" style="background:var(--green-tint)"><b style="color:var(--green)">🛡 Maadoo ดูแลใบสมัคร</b><p style="margin:4px 0 0;font-size:.88rem">บริษัทเงียบ 3 วัน เราเตือนให้ · 14 วันไม่ตอบ คืน Slot ให้อัตโนมัติ</p></div><button class="btn d" data-report="${j.id}">⚑ รายงานประกาศนี้</button><a class="btn" style="text-align:center" href="#co-${j.id}">${ico('user')} ดูโปรไฟล์และรีวิวบริษัท ›</a></aside></div>
 <div class="mbar"><button class="btn aib" data-aicheck="${j.id}">${ico('spark')} AI ตรวจ</button><button class="btn y" data-apply="${j.id}" ${applied?'disabled':''}>${applied?'สมัครแล้ว ✓':'สมัครงานนี้'}</button></div>`};
V.apps=()=>{const n=activeApps();return `<div class="sec" style="margin-top:0"><h1 style="font-size:1.5rem">ใบสมัครของฉัน</h1></div>
 <div class="box" style="margin-bottom:14px"><div style="display:flex;justify-content:space-between"><b>Slot สมัครที่ใช้อยู่</b><b>${n} / ${S.slotLimit}</b></div><div class="slotbar" style="margin-top:6px" role="progressbar" aria-valuemin="0" aria-valuemax="${S.slotLimit}" aria-valuenow="${n}" aria-label="Slot ที่ใช้"><i style="width:${Math.min(100,n/S.slotLimit*100)}%"></i></div><p class="meta" style="margin:6px 0 0">Slot คืนเมื่อบริษัทตอบ หรือเมื่อคุณถอนใบสมัคร</p></div>
 <div class="col">${S.apps.length?S.apps.map((a,i)=>{const j=job(a.job);const st={wait:['รอบริษัทตอบ · วันที่ '+a.day+' จาก 14','o','var(--orange)'],invite:['เชิญสัมภาษณ์ · เลือกเวลา','','var(--blue)'],booked:['นัดสัมภาษณ์แล้ว · '+(a.picked||''),'g','var(--green)'],withdrawn:['ถอนใบสมัครแล้ว','r','var(--muted)'],train:['กำลังฝึกงาน · สัปดาห์ 12 จาก 12','p','var(--purple)'],done:['ฝึกงานเสร็จ · ได้รับใบรับรองแล้ว','g','var(--green)']}[a.status];
 return `<article class="box app" style="border-left-color:${st[2]}"><div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap"><div><h2 style="font-size:1.05rem"><a href="#job-${j.id}">${j.t}</a></h2><div class="meta">${j.co}</div></div><span class="chip ${st[1]}">${st[0]}</span></div>
 <ol class="timeline" aria-label="ไทม์ไลน์">${a.tl.map(t=>`<li>✅ ${esc(t)}</li>`).join('')}${a.status==='wait'||a.status==='invite'?`<li>⏳ ผลสุดท้าย · เหลือเวลา <b class="cdl" data-cd="${DUE0+(14-(a.day||0))*864e5}"></b></li>`:''}</ol>
 ${a.status==='invite'?`<fieldset style="border:0;padding:0;margin:0"><legend style="font-weight:700;color:var(--ink);margin-bottom:6px">เลือกเวลาสัมภาษณ์ (ออนไลน์ · มีคำบรรยายสด)</legend><div class="chips" style="gap:8px">${a.slots.map(s=>`<button class="pill" data-slot="${i}" data-v="${s}">${s}</button>`).join('')}</div></fieldset>`:''}
 ${trainBlock(a,i)}${!['withdrawn','train','done'].includes(a.status)?`<div style="margin-top:8px"><button class="btn d" data-withdraw="${i}">ถอนใบสมัคร</button></div>`:''}</article>`}).join(''):'<div class="box empty">ยังไม่มีใบสมัคร · <a href="#jobs">ไปหางาน</a></div>'}</div>`};
V.gigs=()=>`<div class="sec" style="margin-top:0"><h1 style="font-size:1.5rem">ฟรีแลนซ์จากนักศึกษา</h1></div><p class="meta" style="margin-top:-6px">จ้างงานสั้นจากนักศึกษา จ่ายผ่านระบบกลาง เงินถึงนักศึกษาเมื่อคุณกดอนุมัติงาน</p><div class="grid">${GIGS.map(gigCard).join('')}</div>`;
let pkSel=1;
V.gig=id=>{const g=GIGS.find(x=>x.id===+id)||GIGS[0];const p=g.pk[pkSel];
 return `<p class="meta"><a href="#gigs">ฟรีแลนซ์จากนักศึกษา</a></p><div class="detail"><div class="col"><h1 style="font-size:1.6rem">${g.t}</h1>${gallery(g,'ตัวอย่างผลงานของฟรีแลนซ์')}
 <div class="box stats"><span class="av" style="background:var(${g.c});width:52px;height:52px;border-radius:50%" aria-hidden="true">${g.ini}</span><div style="flex:1;min-width:160px"><b style="color:var(--ink)">${g.who}</b> <span class="chip g">✓ ยืนยันตัวตนนักศึกษา</span><div class="meta">★ ${g.r} (${g.n} รีวิว)</div></div>${['ตอบแชท','ส่งตรงเวลา','จ้างซ้ำ'].map((l,i)=>`<div class="stat"><b>${g.stats[i]}</b><span>${l}</span></div>`).join('')}</div>
 <div class="box"><h2 style="font-size:1rem">ขั้นตอนการทำงาน</h2><ol class="list"><li>คุยบรีฟในแชท</li><li>รับใบเสนอราคา แล้วชำระเข้าระบบกลาง</li><li>ส่งงาน · ขอแก้ได้ตามแพ็กเกจ</li><li>อนุมัติ แล้วเงินจึงโอนให้นักศึกษา</li></ol></div>
 <div class="box"><h2 style="font-size:1rem">รีวิวจากผู้ว่าจ้าง</h2><p style="margin:4px 0 0">“ส่งไว แก้ตามที่ขอครบ” <span class="meta">· ร้านกาแฟ ตัวอย่าง</span></p></div></div>
 <aside class="sticky"><div class="box pricebox" style="padding:0;overflow:hidden"><div class="tabs" role="tablist" aria-label="แพ็กเกจ">${g.pk.map((k,i)=>`<button role="tab" aria-selected="${i===pkSel}" data-pk="${i}" data-gid="${g.id}">${k[0]}</button>`).join('')}</div>
 <div style="padding:14px 16px" role="tabpanel"><div style="display:flex;justify-content:space-between;align-items:baseline;gap:8px"><b style="color:var(--ink)">${p[2]}</b><span class="big">฿${p[1].toLocaleString()}</span></div>
 <div class="chips" style="margin:8px 0"><span class="chip">⏱ ส่งงาน ${p[3]} วัน</span><span class="chip">🔁 แก้ได้ ${p[4]} ครั้ง</span></div><ul class="list" style="font-size:.9rem"><li>ไฟล์ต้นฉบับ</li><li>ใช้เชิงพาณิชย์ได้</li><li>มีข้อความ alt สำหรับโปรแกรมอ่านจอ</li></ul>
 <a class="btn y full" style="display:block;text-align:center;margin-top:10px" href="#chat">แชทสอบถาม / จ้างงาน</a></div></div>
 <div class="box" style="background:var(--green-tint)"><b style="color:var(--green)">🛡 จ่ายผ่านระบบกลาง</b><p style="margin:4px 0 0;font-size:.88rem">เงินพักไว้ที่ Maadoo จนกว่าคุณจะอนุมัติงาน</p></div></aside></div>`};
const STEPS=[['สร้างใบเสนอราคา','ตกลงขอบเขต ราคา กำหนดส่ง'],['ชำระเข้าระบบกลาง','เงินพักไว้ที่ Maadoo'],['กำลังทำงาน','ส่งงานภายใน 18 ธ.ค.'],['ส่งงาน / ขอแก้ไข','อนุมัติ หรือขอแก้ (เหลือ 3 ครั้ง)'],['อนุมัติ & โอนเงิน','รีวิวให้กันและกัน']];
const CHATMSG=[[],['ผู้ว่าจ้างยอมรับใบเสนอราคา และชำระ ฿1,200 เข้าระบบกลางแล้ว'],['นักศึกษาเริ่มทำงาน'],['นักศึกษาส่งงานแล้ว: post-set-v1.pdf'],['อนุมัติงานแล้ว · โอน ฿1,056 ให้นักศึกษา (หัก GP 12%)']];
V.chat=()=>{const s=S.chat;const act=[['ยอมรับและชำระเข้าระบบกลาง','next'],['เริ่มทำงาน (ฝั่งนักศึกษา)','next'],['ส่งงาน (ฝั่งนักศึกษา)','next'],['อนุมัติงาน','next'],null][s];
 return `<div class="sec" style="margin-top:0"><h1 style="font-size:1.5rem">แชทงานฟรีแลนซ์</h1><button class="btn" id="chatReset">เริ่มจำลองใหม่</button></div>
 <div class="chatw"><div class="pane list1" aria-label="รายการแชท">${[['ร้านกาแฟ ตัวอย่าง',['เสนอราคาแล้ว','ชำระแล้ว','กำลังทำงาน','รอตรวจงาน','เสร็จสิ้น'][s],1],['สตูดิโอ ตัวอย่าง','คุยรายละเอียด',0],['ร้านขนม ตัวอย่าง','เสร็จสิ้น',0]].map(c=>`<div class="box" style="padding:9px 11px;${c[2]?'border:2px solid var(--blue)':''}"><b style="font-size:.9rem;color:var(--ink)">${c[0]}</b><div><span class="chip ${c[1]==='เสร็จสิ้น'?'g':''}">${c[1]}</span></div></div>`).join('')}</div>
 <div class="pane" style="background:var(--bg)"><div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:6px"><b style="color:var(--ink)">ร้านกาแฟ ตัวอย่าง</b><span class="meta">🎙 พิมพ์ด้วยเสียง · 💬 คำบรรยาย · 🎧 อ่านข้อความเสียงเป็นตัวอักษร</span></div>
 <div class="msgs" id="msgs" aria-live="polite"><div class="m">อยากได้โพสต์โปรโมชันปีใหม่ 5 ชิ้นค่ะ โทนอบอุ่น</div><div class="m me">ได้เลยครับ ส่งใบเสนอราคาให้นะครับ</div>
 <div class="quote"><b style="color:var(--blue)">📄 ใบเสนอราคา #Q-0193</b><div style="font-size:.9rem">โพสต์ 5 ชิ้น + สตอรี่ 2 ชิ้น<br>฿1,200 · ส่ง 18 ธ.ค. · แก้ได้ 3 ครั้ง</div></div>
 ${CHATMSG.slice(1,s+1).map(m=>`<div class="m sys">${m}</div>`).join('')}<div class="m">🎧 ข้อความเสียง 0:18 · “ขอสีส้มเพิ่มนิดนึงนะคะ”</div>${(S.msgs||[]).map(m=>m[0]==='\u0001'?`<div class="m">${esc(m.slice(1))}</div>`:`<div class="m me">${esc(m)}</div>`).join('')}</div>
 <form id="chatForm" style="display:flex;gap:8px"><label class="sr" for="chatIn">ข้อความ</label><input id="chatIn" style="flex:1;border:1.5px solid var(--line);border-radius:20px;padding:10px 14px;font:inherit;background:var(--surface);color:var(--text);min-width:0" placeholder="พิมพ์ข้อความ…"><button class="btn b">ส่ง</button></form></div>
 <div class="pane" aria-label="สถานะงาน"><b style="color:var(--ink)">สถานะงาน · ฿1,200</b><ol class="steps">${STEPS.map((x,i)=>`<li class="${i<s+1&&!(i===s&&s<4)?'done':''} ${i===s?'now':''}" ${i===s?'aria-current="step"':''}><span class="n">${i<s?'✓':i+1}</span><div><b style="font-size:.9rem;color:var(--ink)">${x[0]}</b><div class="meta">${x[1]}</div></div></li>`).join('')}</ol>
 ${act?`<button class="btn y full" id="chatNext">${act[0]}</button>`:'<div class="box" style="background:var(--green-tint);color:var(--green);font-weight:700">เสร็จสิ้น · ขอบคุณที่ใช้ระบบกลาง</div>'}${s===3?'<button class="btn full" id="chatRev">ขอแก้ไขงาน</button>':''}
 <p class="notice">ปุ่มเหล่านี้จำลองทั้งสองฝั่งเพื่อให้เห็นครบ 5 ขั้น</p></div></div>`};
V.programs=()=>`<div class="sec" style="margin-top:0"><h1 style="font-size:1.5rem">ทดลองทำงานจริง (Career Experience)</h1></div><p class="meta" style="margin-top:-6px">ทำงานจริงกับบริษัทพันธมิตร 1–4 สัปดาห์ มีพี่เลี้ยง ได้ใบรับรองและผลงาน · ไม่รับประกันการจ้างงาน · ทุกโครงการในหน้านี้เป็นตัวอย่าง</p><div class="grid">${PROGRAMS.map(progCard).join('')}</div>
 <div class="box" style="margin-top:16px"><h2 style="font-size:1.05rem">จบโครงการแล้ว ข้อมูลไหลต่อเอง</h2><p style="margin:6px 0 0">ทักษะที่พี่เลี้ยงยืนยัน <span class="chip g">✓ Verified by Mentor</span> → โปรไฟล์ทักษะ → ผลงานลง Portfolio → เรซูเม่ → งานแนะนำที่ตรงขึ้น</p></div>`;
function rScore(r){const k=[r.name,r.role,r.email&&r.phone,(r.intro||'').length>=60,r.edu,(r.skills||'').split(',').filter(x=>x.trim()).length>=3];return Math.round(k.filter(Boolean).length/k.length*100)}
function paper(r){const sk=(r.skills||'').split(',').map(s=>s.trim()).filter(Boolean);return `<div class="ps" style="background:${r.color}1F"><div style="width:64px;height:64px;border-radius:50%;background:#E3EAF5;display:grid;place-items:center;font-weight:700;font-size:1.4rem;color:${r.color}">${esc((r.name||'?')[0])}</div><h4 style="color:${r.color}">ติดต่อ</h4><div style="word-break:break-all">${esc(r.email)}<br>${esc(r.phone)}</div><h4 style="color:${r.color}">ทักษะ</h4>${sk.map(s=>`<span class="skill">${esc(s)}</span>`).join('')}</div>
 <div class="pm"><div class="nm">${esc(r.name)||'ชื่อของคุณ'}</div><div style="color:${r.color};font-weight:700;margin-top:2px">${esc(r.role)}</div><h4 style="color:${r.color};border-bottom:2px solid ${r.color}">แนะนำตัว</h4><div>${esc(r.intro)}</div><h4 style="color:${r.color};border-bottom:2px solid ${r.color}">การศึกษา</h4><div>${esc(r.edu)}</div>${r.cert?`<h4 style="color:${r.color};border-bottom:2px solid ${r.color}">ประสบการณ์ฝึกงาน</h4><div><b>ฝึกงาน Digital Marketing</b> · ตัวอย่าง มีเดีย<br><small>25 ส.ค. – 14 พ.ย. 2569 · 480 ชม. · ใบรับรองเลขที่ ${CERT.no}</small></div>`:''}</div>`}
V.resume=()=>{const r=S.resume;const sc=rScore(r);const f=(id,l,t)=>`<div class="fld"><label for="r_${id}">${l}</label>${t==='ta'?`<textarea id="r_${id}" data-r="${id}" rows="3" maxlength="600">${esc(r[id])}</textarea>`:`<input id="r_${id}" data-r="${id}" value="${esc(r[id])}" ${t?`type="${t}"`:''}>`}</div>`;
 return `<div class="sec" style="margin-top:0"><h1 style="font-size:1.5rem">ทำเรซูเม่ฟรี</h1><span class="chip g">✓ ฟรี 100% · ไม่มีลายน้ำ · ไม่ต้องสมัครสมาชิก</span></div>
 <div class="rb"><div class="col"><div class="box"><div style="display:flex;justify-content:space-between"><b style="color:var(--ink)">เรซูเม่ครบ</b><b id="rPct">${sc}%</b></div><div class="prog" style="margin-top:6px" role="progressbar" aria-valuenow="${sc}" aria-valuemin="0" aria-valuemax="100" aria-label="ความครบของเรซูเม่"><i id="rBar" style="width:${sc}%"></i></div><p class="meta" id="rHint" aria-live="polite" style="margin:6px 0 0">${sc>=100?'🎉 ครบแล้ว! พร้อมใช้สมัครงาน':'เติมแนะนำตัวอย่างน้อย 60 ตัวอักษร และทักษะ 3 อย่าง'}</p></div>
 <div class="box col"><b style="color:var(--ink)">สีหลัก</b><div style="display:flex;gap:10px">${['#2F6FD6','#0F766E','#B4462F','#6D28D9','#1F2937'].map(c=>`<button class="swatch" style="background:${c}" data-color="${c}" aria-pressed="${r.color===c}" aria-label="สี ${c}"></button>`).join('')}</div>
 ${f('name','ชื่อ-นามสกุล')}${f('role','ตำแหน่งที่อยากสมัคร')}<div class="two">${f('email','อีเมล','email')}${f('phone','เบอร์โทร','tel')}</div>${f('intro','แนะนำตัว (2–3 ประโยค)','ta')}${f('edu','การศึกษา')}${f('skills','ทักษะ (คั่นด้วย ,)')}
 <button class="btn y" id="rDl">⬇ ดาวน์โหลด PDF</button></div></div>
 <div><div class="paper" id="paper" aria-label="ตัวอย่างเรซูเม่">${paper(r)}</div><p class="notice">ตัวอย่างอัปเดตทันทีที่พิมพ์ · บันทึกไว้ในเครื่องนี้</p>
 <div class="box" style="margin-top:12px"><div style="display:flex;justify-content:space-between;align-items:center;gap:8px"><h2 style="font-size:1.05rem">${ico('user')} ให้ HR ตัวจริงช่วยดู</h2><span class="chip g">ไม่บังคับ</span></div><p class="meta" style="margin:4px 0 8px">ทำเรซูเม่ฟรีเสมอ · บริการเสริมสำหรับคนอยากได้คำแนะนำจากคนทำงานจริง</p>
 ${[['doc','ตรวจเรซูเม่','HR อ่านแล้วบอกจุดที่ควรแก้ ตอบกลับภายใน 3 วัน','฿99','ตรวจเรซูเม่'],['chat','ซ้อมสัมภาษณ์ 30 นาที','คุยออนไลน์กับรุ่นพี่/HR ตามตำแหน่งที่อยากสมัคร','฿199','ซ้อมสัมภาษณ์']].map(s=>`<div class="hrrow"><span class="cic">${ico(s[0])}</span><div style="flex:1;min-width:0"><b style="color:var(--ink)">${s[1]}</b><div class="meta">${s[2]}</div></div><button class="btn y" data-hr="${s[4]}">${s[3]}</button></div>`).join('')}
 <p class="notice" style="margin:8px 0 0">อยากคุยแบบสบายๆ ก่อน? <a href="#mentor">ปรึกษาพี่เลี้ยง</a> · ราคาและผู้ให้บริการในเดโมเป็นตัวอย่าง</p></div></div></div>`};
V.company=()=>`<div class="sec" style="margin-top:0"><h1 style="font-size:1.5rem">สำหรับบริษัท</h1></div><div class="two"><div class="box col"><h2 style="font-size:1.1rem">ลงประกาศงานที่ครอบคลุม</h2><p style="margin:0">ฟรี 3 เดือนแรก · หลังจากนั้น ฿2,500/เดือน</p>
 <fieldset style="border:0;padding:0;margin:0"><legend style="font-weight:700;color:var(--ink);margin-bottom:6px">การรองรับในที่ทำงาน</legend><div class="chips" style="gap:8px">${Object.keys(ACC).map((k,i)=>`<button class="pill" aria-pressed="${i<2}" data-toggle>${ACC[k]}</button>`).join('')}</div></fieldset>
 <div class="fld"><label for="cdesc">คุณสมบัติ</label><textarea id="cdesc" rows="3">สุขภาพแข็งแรง บุคลิกดี จบวิทยาศาสตร์</textarea></div><button class="btn b" id="checkWords">🤖 ตรวจถ้อยคำในประกาศ</button><div id="wordRes" aria-live="polite"></div></div>
 <div class="box col"><h2 style="font-size:1.1rem">ผู้สมัครที่แนะนำ · Graphic Designer</h2>${[['น้ำใส',87,'Photoshop สูง · Illustrator กลาง · Portfolio',''],['ต้นกล้า',76,'Photoshop กลาง · CorelDRAW ≈ Illustrator',''],['เมฆ',63,'ทักษะจำเป็นครบในระดับเริ่มต้น','p']].map(c=>`<div class="box" style="display:flex;gap:10px;align-items:center">${ring(c[1],c[3]?'var(--purple)':'var(--green)')}<div style="flex:1;min-width:0"><b style="color:var(--ink)">${c[0]}</b> ${c[3]?'<span class="chip p">🌱 มีศักยภาพพัฒนาต่อได้</span>':''}<div class="meta">${c[2]}</div></div><button class="btn" data-contact="${c[0]}">ติดต่อ</button></div>`).join('')}<p class="notice" style="margin:0">แสดงผู้สมัครทุกคน ไม่มีการคัดออกอัตโนมัติ · ไม่ใช้อายุ เพศ หรือความพิการในคะแนน</p></div></div>`;
V.access=()=>`<div class="box col" style="max-width:760px"><h1 style="font-size:1.5rem">คำแถลงการเข้าถึง</h1><p style="margin:0">เราออกแบบ Maadoo ให้ใช้ได้ตามแนวทาง WCAG 2.2 ระดับ AA</p><ul class="list"><li>ใช้คีย์บอร์ดได้ทุกหน้า · มีลิงก์ “ข้ามไปเนื้อหาหลัก”</li><li>ปรับขนาดตัวอักษร สีตัดกันชัด ระยะบรรทัด และลดภาพเคลื่อนไหวได้จากปุ่ม <i class="ico ic-access" aria-hidden="true"></i></li><li>การ์ดงานอ่านเป็นประโยคเดียวสำหรับโปรแกรมอ่านจอ</li><li>ค้นงานจากการรองรับ ไม่ถามประเภทความพิการ · ข้อมูลการปรับแชร์เฉพาะเมื่อคุณเลือก</li></ul><p class="meta" style="margin:0">เดโมนี้ยังไม่ได้ทดสอบกับผู้ใช้คนพิการจริง · พบปัญหาแจ้งทีมผ่านหน้าโครงการ</p></div>`;

function setCurrent(name){document.querySelectorAll('#subnav a,#bnav a').forEach(a=>{const h=a.getAttribute('href').slice(1);if(h===name||(name.startsWith('job-')&&h==='jobs')||(name.startsWith('gig-')&&h==='gigs'))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')})}
function render(focus){const h=(location.hash||'#home').slice(1);let html,name=h;
 if(h.startsWith('job-'))html=V.job(h.slice(4));else if(h.startsWith('gig-'))html=V.gig(h.slice(4));else if(h.startsWith('co-'))html=V.co(h.slice(3));else if(h.startsWith('cert-')){html=V.cert(h.slice(5));name='apps'}else if(V[h])html=V[h]();else{html=V.home();name='home'}
 $('#view').innerHTML=html;setCurrent(name);document.title=({home:'Maadoo Job Demo',jobs:'หางาน · Maadoo',inclusive:'งานที่รองรับคนพิการ · Maadoo',apps:'ใบสมัครของฉัน · Maadoo',resume:'ทำเรซูเม่ฟรี · Maadoo',chat:'แชทงาน · Maadoo'})[name]||'Maadoo Job Demo';
 if(focus){window.scrollTo(0,0);$('#main').focus({preventScroll:true})}
 enhance(focus)}
window.addEventListener('hashchange',()=>{if(location.hash==='#inclusive'){S.f.acc=S.f.acc.length?S.f.acc:[]}render(true)});

/* events */
document.addEventListener('click',e=>{const t=e.target.closest('button,[data-q],[data-cat]');if(!t)return;
 if(t.dataset.save){const id=+t.dataset.save;S.saved=S.saved.includes(id)?S.saved.filter(x=>x!==id):[...S.saved,id];save();render();toast(S.saved.includes(id)?'บันทึกงานแล้ว':'เลิกบันทึกแล้ว');return}
 if(t.dataset.q!==undefined&&t.dataset.q){S.f={...S.f,q:t.dataset.q,cat:''};location.hash='jobs';return}
 if(t.dataset.go){location.hash=t.dataset.go;return}
 if(t.dataset.cat){S.f={...S.f,cat:t.dataset.cat,q:''};location.hash='jobs';render(true);return}
 if(t.id==='clearF'){S.f={q:'',types:[],modes:[],acc:[],verified:false,sort:'match',cat:'',loc:'',minPay:0,fast:false};render();live('ล้างตัวกรองแล้ว');return}
 if(t.dataset.apply){openApply(+t.dataset.apply);return}
 if(t.dataset.share){toast('คัดลอกลิงก์งานไว้ส่งใน LINE แล้ว (เดโม)');try{navigator.clipboard.writeText('maadoo.pages.dev/jobs/'+t.dataset.share).catch(()=>{})}catch(_){}return}
 if(t.dataset.report){openModal(`<h2 style="font-size:1.2rem">รายงานประกาศงาน</h2><fieldset style="border:0;padding:0;margin:0;display:flex;flex-direction:column;gap:8px"><legend class="sr">เหตุผล</legend>${['ขอเก็บเงินจากผู้สมัคร','งานหลอกลวง / ไม่มีอยู่จริง','ข้อมูลไม่ตรงความจริง','ระบุการรองรับคนพิการไม่ตรงจริง','ขอข้อมูลส่วนตัวเกินจำเป็น'].map((r,i)=>`<label><input type="radio" name="rep" ${i?'':'checked'}> ${r}</label>`).join('')}</fieldset><div style="display:flex;gap:8px"><button class="btn" data-close>ยกเลิก</button><button class="btn y" data-close data-msg="ส่งรายงานแล้ว ทีมจะตรวจภายใน 3 วันทำการ">ส่งรายงาน</button></div>`,'รายงานประกาศงาน');return}
 if(t.dataset.slot!==undefined){const a=S.apps[+t.dataset.slot];a.status='booked';a.picked=t.dataset.v;a.tl.push('ยืนยันเวลาสัมภาษณ์ · '+t.dataset.v);save();render();toast('ยืนยันเวลาแล้ว ส่งอีเมลยืนยันให้ทั้งสองฝ่าย');return}
 if(t.dataset.withdraw!==undefined){const i=+t.dataset.withdraw;openModal(`<h2 style="font-size:1.2rem">ถอนใบสมัครนี้?</h2><p style="margin:0">บริษัทจะได้รับแจ้ง และ Slot จะคืนให้ทันที ถอนแล้วสมัครซ้ำได้</p><div style="display:flex;gap:8px"><button class="btn" data-close>ไม่ถอน</button><button class="btn d" id="doWithdraw" data-i="${i}">ยืนยันถอน</button></div>`,'ถอนใบสมัคร');return}
 if(t.id==='doWithdraw'){const a=S.apps[+t.dataset.i];a.status='withdrawn';a.tl.push('ถอนใบสมัคร');save();closeModal();render();toast('ถอนใบสมัครแล้ว · คืน Slot แล้ว');return}
 if(t.dataset.pk!==undefined){pkSel=+t.dataset.pk;render();const b=document.querySelector(`[data-pk="${pkSel}"]`);b&&b.focus();return}
 if(t.id==='chatNext'){S.chat=Math.min(4,S.chat+1);save();render();live(STEPS[S.chat][0]);if(S.chat===4)toast('อนุมัติงานแล้ว · โอนเงินให้นักศึกษา');return}
 if(t.id==='chatRev'){S.msgs=[...(S.msgs||[]),'ขอปรับสีส้มเพิ่มนิดนึงครับ (ขอแก้ครั้งที่ 1)'];S.chat=2;save();render();toast('ส่งคำขอแก้ไขแล้ว · เหลือแก้ได้ 2 ครั้ง');return}
 if(t.id==='chatReset'){S.chat=0;S.msgs=[];save();render();return}
 if(t.dataset.color){S.resume.color=t.dataset.color;save();render();return}
 if(t.id==='rDl'){toast('ในแอปจริงจะเปิดหน้าต่างบันทึกเป็น PDF ขนาด A4 · เดโมนี้ปิดการพิมพ์ไว้');return}
 if(t.hasAttribute('data-toggle')){t.setAttribute('aria-pressed',t.getAttribute('aria-pressed')!=='true');return}
 if(t.id==='checkWords'){const v=$('#cdesc').value;const out=[];if(/สุขภาพแข็งแรง/.test(v))out.push('“สุขภาพแข็งแรง” อาจกันผู้สมัครโดยไม่จำเป็น → ระบุสิ่งที่ต้องทำจริง เช่น “ยกของไม่เกิน 5 กก. มีรถเข็นช่วย”');if(/บุคลิกดี/.test(v))out.push('“บุคลิกดี” ไม่เกี่ยวกับเนื้องาน → แนะนำให้ลบ');if(/อายุ|เพศ/.test(v))out.push('การระบุอายุหรือเพศ → ใช้เฉพาะเมื่อจำเป็นตามกฎหมาย');$('#wordRes').innerHTML=out.length?`<div class="box" style="border:2px solid var(--orange)"><ul class="list" style="margin:0">${out.map(o=>`<li>⚠ ${o}</li>`).join('')}</ul></div>`:'<div class="box" style="background:var(--green-tint);color:var(--green)">✓ ไม่พบถ้อยคำที่กีดกันโดยไม่จำเป็น</div>';return}
 if(t.dataset.contact){toast('ส่งคำเชิญถึง '+t.dataset.contact+' แล้ว (เดโม)');return}
 if(t.id==='bellBtn'){openModal(`<h2 style="font-size:1.2rem">การแจ้งเตือน</h2><div class="box">📅 ซีเมนส์ ไบโอ แล็บ เชิญสัมภาษณ์ · <a href="#apps" data-close>เลือกเวลา</a></div><div class="box">📨 เราเตือนไบโอเฟรช ฟู้ดส์ให้แล้ว (วันที่ 3)</div><button class="btn" data-close>ปิด</button>`,'การแจ้งเตือน');return}
 if(t.hasAttribute('data-close')){if(t.dataset.msg)toast(t.dataset.msg);closeModal();return}
});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.f){const g=t.dataset.f;if(g==='verified')S.f.verified=t.checked;else{S.f[g]=t.checked?[...S.f[g],t.value]:S.f[g].filter(x=>x!==t.value)}render();live('พบ '+filtered().length+' งาน');const el=document.querySelector(`[data-f="${g}"]${g==='verified'?'':`[value="${t.value}"]`}`);el&&el.focus()}
 if(t.id==='sortSel'){S.f.sort=t.value;render();$('#sortSel').focus();live('เรียงใหม่แล้ว')}});
let rT;document.addEventListener('input',e=>{const t=e.target;if(t.dataset.r){S.resume[t.dataset.r]=t.value;clearTimeout(rT);rT=setTimeout(save,250);const sc=rScore(S.resume);$('#paper').innerHTML=paper(S.resume);$('#rPct').textContent=sc+'%';$('#rBar').style.width=sc+'%';$('#rHint').textContent=sc>=100?'🎉 ครบแล้ว! พร้อมใช้สมัครงาน':'เติมแนะนำตัวอย่างน้อย 60 ตัวอักษร และทักษะ 3 อย่าง'}});
document.addEventListener('submit',e=>{e.preventDefault();const t=e.target;
 if(t.id==='topSearch'){S.f={...S.f,q:$('#topQ').value.trim(),loc:$('#topLoc').value.trim(),cat:''};const ty=$('#topCat').value;S.f.types=ty?[ty]:[];if(location.hash==='#jobs')render(true);else location.hash='jobs'}
 if(t.id==='jobSearch'){S.f={...S.f,q:$('#jobQ').value.trim(),loc:$('#jobLoc').value.trim(),cat:''};render();live('พบ '+filtered().length+' งาน');$('#jobQ').focus()}
 if(t.id==='heroSearch'){S.f={...S.f,q:$('#heroQ').value.trim(),loc:$('#heroLoc').value.trim(),cat:''};location.hash='jobs'}
 if(t.id==='chatForm'){const v=$('#chatIn').value.trim();if(v){S.msgs=[...(S.msgs||[]),v];render();$('#chatIn').focus();botReply()}}
 if(t.id==='applyForm'){doApply(+t.dataset.job,t)}
});

/* modal */
let lastFocus;
function openModal(inner,label){lastFocus=document.activeElement;$('#layer').innerHTML=`<div class="ov" data-ov><div class="modal" role="dialog" aria-modal="true" aria-label="${label}">${inner}</div></div>`;const m=$('.modal');const f=m.querySelector('input,button,textarea,a,select');f&&f.focus();m.addEventListener('keydown',trap)}
function closeModal(){$('#layer').innerHTML='';lastFocus&&lastFocus.focus&&lastFocus.focus()}
function trap(e){if(e.key==='Escape'){closeModal();return}if(e.key!=='Tab')return;const els=[...$('.modal').querySelectorAll('button,input,textarea,a,select')].filter(x=>!x.disabled);if(!els.length)return;const a=els[0],b=els[els.length-1];if(e.shiftKey&&document.activeElement===a){e.preventDefault();b.focus()}else if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a.focus()}}
document.addEventListener('mousedown',e=>{if(e.target.matches('[data-ov]'))closeModal()});
function openApply(id){const j=job(id);if(activeApps()>=S.slotLimit){openModal(`<h2 style="font-size:1.2rem">Slot เต็มแล้ว (${S.slotLimit}/${S.slotLimit})</h2><p style="margin:0">รอบริษัทตอบแล้ว Slot จะคืนให้เอง หรือเพิ่ม Slot</p><div class="box"><b>Extra Slot 1 ที่</b> · ฿39 / 7 วัน</div><div class="box"><b>Plus · 5 Slot</b> · ฿99 / เดือน</div><div style="display:flex;gap:8px"><button class="btn" data-close>รอ Slot คืน</button><button class="btn y" id="buySlot">เพิ่ม Extra Slot (เดโม)</button></div>`,'Slot เต็ม');$('#buySlot').onclick=()=>{S.slotLimit++;closeModal();toast('เพิ่ม Slot แล้ว (เดโม ไม่มีการตัดเงิน)');openApply(id)};return}
 openModal(`<form id="applyForm" data-job="${id}" class="col"><h2 style="font-size:1.2rem">สมัคร: ${j.t}</h2>
 <fieldset style="border:0;padding:0;margin:0" class="col"><legend style="font-weight:700;color:var(--ink);margin-bottom:6px">ส่งเรซูเม่ไหน</legend><label class="box" style="display:flex;gap:8px"><input type="radio" name="cv" value="maadoo" checked> 📄 เรซูเม่จาก Maadoo · ${esc(S.resume.name)} (ครบ ${rScore(S.resume)}%)</label><label class="box" style="display:flex;gap:8px"><input type="radio" name="cv" value="pdf"> ⬆ อัปโหลด PDF เอง</label></fieldset>
 <fieldset style="border:0;padding:0;margin:0" class="col"><legend style="font-weight:700;color:var(--ink);margin-bottom:6px">ช่องทางที่ให้บริษัทติดต่อกลับ</legend><div class="chips" style="gap:6px">${[['chat','แชทใน Maadoo'],['line','LINE'],['mail','อีเมล'],['tel','โทร']].map((c,i)=>`<label class="pill chn"><input type="radio" name="ch" value="${c[0]}" ${i===0?'checked':''} style="position:absolute;opacity:0"> ${c[1]}</label>`).join('')}</div></fieldset>
 <div class="fld"><label for="apTel">เบอร์โทร (กรอกจากเรซูเม่)</label><input id="apTel" value="${esc(S.resume.phone)}"></div>
 <div class="fld"><label for="apMsg">ข้อความถึงบริษัท (ไม่บังคับ)</label><textarea id="apMsg" rows="2" maxlength="300"></textarea></div>
 <fieldset style="border:0;padding:0;margin:0"><legend style="font-weight:700;color:var(--ink);margin-bottom:6px">ขอการปรับสำหรับการสัมภาษณ์ (ไม่บังคับ)</legend><div class="chips" style="gap:8px">${['สัมภาษณ์ออนไลน์','คำบรรยายสด','ล่ามภาษามือ','ขอเวลาเพิ่ม','เอกสารที่อ่านจอได้','สถานที่มีทางลาด'].map(x=>`<button type="button" class="pill" aria-pressed="false" data-toggle>${x}</button>`).join('')}</div><p class="meta" style="margin:6px 0 0">บริษัทเห็นเฉพาะสิ่งที่เลือก · ไม่ใช้กับคะแนนความตรง</p></fieldset>
 ${j.acc.includes('m33')?'<div class="box" style="background:var(--orange-tint)"><b>งานนี้รับตามมาตรา 33</b><p style="margin:2px 0 0;font-size:.88rem">บริษัทอาจขอสำเนาบัตรประจำตัวคนพิการหลังผ่านสัมภาษณ์ · ไม่ต้องแนบตอนนี้</p></div>':''}
 <div class="box" style="background:var(--tint)">ใช้ 1 Slot จาก ${S.slotLimit} · คืนเมื่อบริษัทตอบ</div>
 <div style="display:flex;gap:8px"><button type="button" class="btn" data-close>ยกเลิก</button><button class="btn y" style="flex:1">ยืนยันส่งใบสมัคร</button></div></form>`,'สมัครงาน')}
function doApply(id){const req=[...document.querySelectorAll('#applyForm [data-toggle][aria-pressed="true"]')].map(b=>b.textContent);S.apps.unshift({job:id,day:0,status:'wait',tl:['ส่งใบสมัคร · วันนี้'].concat(req.length?['ขอการปรับ: '+req.join(', ')]:[])});save();closeModal();render();toast('ส่งใบสมัครแล้ว · ดูสถานะได้ที่ “ใบสมัครของฉัน”')}
/* a11y panel */
function applyA11y(){const a=S.a11y,h=document.documentElement;h.style.setProperty('--fs',a.fs+'%');['hc','spacing','dys','ul','rm','bigfocus'].forEach(k=>h.classList.toggle(k,!!a[k]));store.set('a11y',a)}
function openA11y(){const a=S.a11y;$('#a11yBtn').setAttribute('aria-expanded','true');const sw=(k,l)=>`<label class="sw"><span>${l}</span><input type="checkbox" role="switch" data-a="${k}" ${a[k]?'checked':''}></label>`;
 $('#layer').innerHTML=`<div class="panel" role="dialog" aria-modal="false" aria-labelledby="a11yT" id="a11yPanel"><div style="display:flex;justify-content:space-between;align-items:center"><h2 id="a11yT" style="font-size:1.15rem;display:flex;align-items:center;gap:8px"><span class="cic"><i class="ico ic-access" aria-hidden="true"></i></span> การช่วยการเข้าถึง</h2><button class="btn" id="a11yClose">ปิด</button></div>
 <fieldset style="border:0;padding:0;margin:0"><legend style="font-weight:700;color:var(--ink);margin-bottom:6px">ขนาดตัวอักษร</legend><div class="chips" style="gap:6px">${[90,100,125,150,200].map(v=>`<button class="pill" data-fs="${v}" aria-pressed="${a.fs===v}">${v}%</button>`).join('')}</div></fieldset>
 ${sw('hc','สีตัดกันชัด (High contrast)')}${sw('spacing','ระยะบรรทัดและตัวอักษรกว้างขึ้น')}${sw('dys','ฟอนต์อ่านง่าย')}${sw('ul','ขีดเส้นใต้ลิงก์ทุกจุด')}${sw('rm','ลดภาพเคลื่อนไหว')}${sw('bigfocus','กรอบโฟกัสใหญ่')}
 <button class="btn" id="a11yReset">คืนค่าเริ่มต้น</button></div>`;
 $('#a11yPanel').querySelector('button').focus();$('#a11yPanel').addEventListener('keydown',e=>{if(e.key==='Escape')closeA11y()})}
function closeA11y(){$('#layer').innerHTML='';$('#a11yBtn').setAttribute('aria-expanded','false');$('#a11yBtn').focus()}
$('#a11yBtn').addEventListener('click',()=>{$('#a11yPanel')?closeA11y():openA11y()});
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;
 if(t.dataset.fs){S.a11y.fs=+t.dataset.fs;applyA11y();document.querySelectorAll('[data-fs]').forEach(b=>b.setAttribute('aria-pressed',b===t));live('ขนาดตัวอักษร '+t.dataset.fs+' เปอร์เซ็นต์')}
 if(t.id==='a11yClose')closeA11y();
 if(t.id==='a11yReset'){S.a11y={fs:100,hc:false,spacing:false,dys:false,ul:false,rm:false,bigfocus:false};applyA11y();openA11y()}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.a){S.a11y[t.dataset.a]=t.checked;applyA11y();live((t.checked?'เปิด ':'ปิด ')+t.parentElement.textContent.trim())}});
document.addEventListener('keydown',e=>{if(e.altKey&&(e.key==='a'||e.key==='A')){e.preventDefault();$('#a11yPanel')?closeA11y():openA11y()}});
$('#themeBtn').addEventListener('click',()=>{const h=document.documentElement;const dark=h.dataset.theme==='dark'||(!h.dataset.theme&&matchMedia('(prefers-color-scheme: dark)').matches);h.dataset.theme=dark?'light':'dark';$('#themeBtn').textContent=dark?'🌙':'☀️'});

/* ===== live / real-time effects ===== */
const DUE0=Date.now()+5*36e5;const LV={};JOBS.forEach(j=>LV[j.id]=3+Math.floor(Math.random()*18));
const FEED=[['พิมพ์ชนก','เพิ่งสมัคร Data Analyst (Junior)','chart'],['ธนากร','บันทึกงาน ฝึกงาน QC ห้องแล็บ','star'],['มนัสนันท์','ได้รับคำเชิญสัมภาษณ์ที่ ซีเมนส์ ไบโอ แล็บ','clock'],['วริษา','เพิ่มใบรับรองฝึกงานลงเรซูเม่','doc'],['กิตติ','ใช้ AI ตรวจความเหมาะสม Graphic Designer','spark'],['ปรีดา','จองซ้อมสัมภาษณ์กับพี่เลี้ยง','chat'],['ศิริพร','กรองงานที่มีล่ามภาษามือ','access']];
const MYF=[['ไบโอเฟรช ฟู้ดส์','เปิดดูใบสมัครของคุณแล้ว','user'],['ซีเมนส์ ไบโอ แล็บ','ส่งเวลาสัมภาษณ์ให้เลือกใหม่','clock']];
let feedI=0,myI=0,feedT;
function feedPop(my){const f=document.createElement('div');f.className='feed'+(my?' my':'');f.setAttribute('aria-hidden','true');const x=my?MYF[myI++%MYF.length]:FEED[feedI++%FEED.length];f.innerHTML=`<span class="cic">${ico(x[2])}</span><div><b>${esc(x[0])}</b><small>${esc(x[1])}</small><em>จำลองเพื่อการสาธิต · เมื่อสักครู่</em></div>`;document.body.appendChild(f);setTimeout(()=>f.classList.add('out'),4200);setTimeout(()=>f.remove(),4700)}
function tickLive(){if(document.hidden||document.body.classList.contains('locked'))return;
 JOBS.forEach(j=>{const n=Math.max(1,Math.min(40,(LV[j.id]||5)+Math.round((Math.random()-.45)*3)));if(n!==LV[j.id]){LV[j.id]=n;document.querySelectorAll('[data-lv="'+j.id+'"]').forEach(el=>{el.textContent=n;el.classList.remove('tk');void el.offsetWidth;el.classList.add('tk')})}});
 const tot=$('#liveTot');if(tot){tot.textContent=Object.values(LV).reduce((a,b)=>a+b,0);tot.classList.remove('tk');void tot.offsetWidth;tot.classList.add('tk')}}
function tickCd(){document.querySelectorAll('[data-cd]').forEach(el=>{let d=Math.max(0,+el.dataset.cd-Date.now());const D=Math.floor(d/864e5),h=Math.floor(d%864e5/36e5),m=Math.floor(d%36e5/6e4),s=Math.floor(d%6e4/1e3);el.textContent=D+' วัน '+[h,m,s].map(v=>String(v).padStart(2,'0')).join(':')})}
function burst(x,y,emoji){const rm=S.a11y.rm||matchMedia('(prefers-reduced-motion: reduce)').matches;if(rm)return;for(let i=0;i<(emoji?7:26);i++){const p=document.createElement('i');p.className=emoji?'hb':'cf';const a=Math.random()*Math.PI*2,r=emoji?40+Math.random()*40:120+Math.random()*180;p.style.cssText=`left:${x}px;top:${y}px;--dx:${Math.cos(a)*r}px;--dy:${Math.sin(a)*r-(emoji?20:80)}px;--c:${['#FFC53D','#2F6FD6','#14866A','#C8344D','#6D28D9'][i%5]};--rot:${Math.random()*720}deg`;if(emoji)p.textContent='♥';document.body.appendChild(p);setTimeout(()=>p.remove(),1300)}}
const BOT=['ได้เลยค่ะ เดี๋ยวส่งตัวอย่างงานให้ดูก่อนนะคะ','รับทราบค่ะ ขอเวลาปรับแก้ประมาณครึ่งวันนะคะ','ขอบคุณที่แจ้งค่ะ เดี๋ยวอัปเดตให้ในแชทนี้เลย'];let botI=0;
function botReply(){const box=$('#msgs');if(!box)return;const ty=document.createElement('div');ty.className='m typ';ty.innerHTML='<i></i><i></i><i></i>';box.appendChild(ty);box.scrollTop=box.scrollHeight;
 setTimeout(()=>{S.msgs=[...(S.msgs||[]),'\u0001'+BOT[botI++%BOT.length]];if(location.hash==='#chat'){render();const b=$('#msgs');b&&(b.scrollTop=b.scrollHeight)}},1700)}
setInterval(tickLive,3200);setInterval(tickCd,1000);
setTimeout(function loop(){if(!document.hidden&&!document.body.classList.contains('locked')&&!document.querySelector('.ov')&&!S.a11y.rm)feedPop(feedI%3===2&&S.apps.some(a=>a.status==='wait'));setTimeout(loop,9000+Math.random()*4000)},9000);
document.addEventListener('mousemove',e=>{const c=e.target.closest&&e.target.closest('.card,.box.pricebox,.accc,.lf');if(c){const r=c.getBoundingClientRect();c.style.setProperty('--sx',(e.clientX-r.left)+'px');c.style.setProperty('--sy',(e.clientY-r.top)+'px')}});
document.addEventListener('click',e=>{const h=e.target.closest('[data-save]');if(h&&h.getAttribute('aria-pressed')==='false'&&!h.closest('#land'))burst(e.clientX,e.clientY,true);
 const u=e.target.closest('[data-upload]');if(u)pickPhotos(u.dataset.upload);const c=e.target.closest('[data-upclear]');if(c){delete PH[c.dataset.upclear];store.set('photos',PH);render();toast('ลบรูปแล้ว')}});
document.addEventListener('submit',e=>{if(e.target.id==='applyForm')setTimeout(()=>burst(innerWidth/2,innerHeight/3),150)});
function pickPhotos(key){const inp=document.createElement('input');inp.type='file';inp.accept='image/*';inp.multiple=true;inp.onchange=async()=>{const fs=[...inp.files].slice(0,5);if(!fs.length)return;const out=PH[key]?[...PH[key]]:[];
 for(const f of fs){if(f.size>10e6){toast('ไฟล์ใหญ่เกิน 10MB: '+f.name);continue}try{const u=await shrink(f);out.push(u)}catch(x){toast('อ่านรูปไม่ได้: '+f.name)}}
 PH[key]=out.slice(0,8);try{localStorage.setItem('maadoo-demo-photos',JSON.stringify(PH))}catch(x){toast('พื้นที่เก็บในเครื่องเต็ม ลองใช้รูปน้อยลง')}render();toast('ใส่รูปแล้ว · เก็บในเครื่องนี้เท่านั้น')};inp.click()}
function shrink(f){return new Promise((res,rej)=>{const im=new Image();const u=URL.createObjectURL(f);im.onload=()=>{const k=Math.min(1,900/Math.max(im.width,im.height));const c=document.createElement('canvas');c.width=Math.round(im.width*k);c.height=Math.round(im.height*k);c.getContext('2d').drawImage(im,0,0,c.width,c.height);URL.revokeObjectURL(u);res(c.toDataURL('image/jpeg',.8))};im.onerror=rej;im.src=u})}
