function openAI(id){const j=job(id);const have=j.skills.filter(s=>s[1]),gap=j.skills.filter(s=>!s[1]);const sc=j.match||60;
 openModal(`<h2 style="font-size:1.2rem">${ico('spark')} AI ตรวจความเหมาะสม</h2><p class="meta" style="margin:0">${j.t} · ${j.co}</p><div class="aiload" id="aiL"><span class="spin"></span> กำลังเทียบเรซูเม่กับงาน…</div><div id="aiR" hidden>
 <div style="display:flex;gap:12px;align-items:center;background:var(--tint);border-radius:16px;padding:10px">${ring(sc,j.potential?'var(--purple)':'var(--green)')}<div><b style="color:var(--ink)">ทักษะตรง ${sc}%</b><div class="meta">${j.potential?'มีศักยภาพพัฒนาต่อได้ — สมัครได้':'เหมาะกับโปรไฟล์ของคุณ'}</div></div></div>
 <div class="two"><div class="box"><b style="color:var(--green)">มีแล้ว</b><ul class="list">${have.map(s=>`<li>✅ ${s[0]}</li>`).join('')||'<li>—</li>'}</ul></div><div class="box"><b style="color:var(--orange)">ยังขาด</b><ul class="list">${gap.map(s=>`<li>⚪ ${s[0]} <small class="meta">ลองเรียนสั้นๆ หรือทำงานตัวอย่าง 1 ชิ้น</small></li>`).join('')||'<li>ไม่มี</li>'}</ul></div></div>
 <div class="box">${j.acc.length?'งานนี้ระบุการรองรับ: '+j.acc.map(k=>ACC[k]).join(' · '):'งานนี้ยังไม่ระบุการรองรับ — ถามบริษัทในใบสมัครได้'}</div>
 <p class="notice" style="margin:0">AI ในเดโมจำลองผลเพื่อช่วยตัดสินใจ ไม่ตัดใครออก และไม่ใช้อายุ เพศ หรือความพิการคำนวณ</p><div style="display:flex;gap:8px"><button class="btn" data-close>ปิด</button><button class="btn y" style="flex:1" data-apply="${j.id}">สมัครงานนี้</button></div></div>`,'AI ตรวจความเหมาะสม');
 setTimeout(()=>{const l=$('#aiL'),r=$('#aiR');if(l&&r){l.hidden=true;r.hidden=false;r.classList.add('pop')}},1300)}

/* ===== TH/EN (partial) ===== */
const EN={'หน้าแรก':'Home','หางาน':'Find jobs','งานที่รองรับคนพิการ':'Inclusive jobs','ฟรีแลนซ์จากนักศึกษา':'Student freelancers','ทดลองทำงานจริง':'Try real work','ปรึกษาพี่เลี้ยง':'Mentors','ใบสมัครของฉัน':'My applications','ทำเรซูเม่ฟรี':'Free résumé','แชทงาน':'Job chat','สำหรับบริษัท':'For employers','ลงประกาศงาน':'Post a job','การเข้าถึง':'Accessibility','ค้นหา':'Search','ค้นหางาน':'Search jobs','ก่อนไปทำงาน':'Before you work,','มาดูก่อน':'look first','ฝึกงาน QC':'QC internship','บาริสต้า':'Barista','งานแนะนำสำหรับคุณ':'Recommended for you','ดูทั้งหมด ›':'See all ›','รองรับคนพิการ':'Disability-friendly','ใบสมัคร':'Applied','ฉัน':'Me','รีวิว':'Review','ตัวกรอง':'Filters','ล้างตัวกรอง':'Clear filters','สมัครงานนี้':'Apply','ดูผลลัพธ์':'Show results','บริษัทยืนยันตัวตน':'Verified employers','รีวิวจากคนเคยทำจริง':'Reviews from real workers','ปิด':'Close','ยกเลิก':'Cancel'};
function applyLang(){const en=S.lang==='en';document.documentElement.lang=en?'en':'th';
 const w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);const ns=[];while(w.nextNode())ns.push(w.currentNode);
 ns.forEach(n=>{if(n.parentNode.closest('script,style,#intro'))return;if(n.__th!==undefined&&!en){n.nodeValue=n.__th;delete n.__th;return}
  if(en&&n.__th===undefined){const k=n.nodeValue.trim();if(EN[k]){n.__th=n.nodeValue;n.nodeValue=n.nodeValue.replace(k,EN[k])}}});
 const lb=$('#langBtn');if(lb)lb.setAttribute('aria-pressed',en)}

/* ===== enhance: reveal, gallery, placeholder rotation, ripple ===== */
const io='IntersectionObserver' in window?new IntersectionObserver(es=>es.forEach(x=>{if(x.isIntersecting){x.target.classList.add('in');io.unobserve(x.target)}}),{threshold:.06}):null;
let galT,rotT,booted=false;
function galSet(g,i){const n=+g.dataset.n;i=(i+n)%n;g.dataset.i=i;g.style.setProperty('--gi',i);g.querySelectorAll('[data-gal-to]').forEach((b,k)=>b.setAttribute('aria-pressed',k===i))}
function enhance(focus){const anim=focus||!booted;booted=true;
 const els=document.querySelectorAll('#view .card,#view .box,#view .sec,#view .cats button,#view .trust div,#view .hero,#view .accc');
 els.forEach((el,i)=>{el.classList.add('rv');if(!anim||!io){el.classList.add('in','nt')}else{el.style.setProperty('--d',(Math.min(i,10)*55)+'ms');io.observe(el)}});
 clearInterval(galT);const g=document.querySelector('[data-gal]');if(g){galSet(g,0);}
 clearInterval(rotT);const ri=document.querySelector('[data-rot]');if(ri){const w=['ลอง “ฝึกงาน QC”','ลอง “Data Analyst”','ลอง “Graphic Designer”','ลอง “พาร์ทไทม์ ใกล้ BTS”'];let k=0;rotT=setInterval(()=>{if(document.activeElement===ri)return;k=(k+1)%w.length;ri.placeholder=w[k]},2200)}
 const fd=document.querySelector('details.ffold');if(fd&&!fd.__b){fd.__b=1;fd.addEventListener('toggle',()=>{if(innerWidth<=860)S.fsOpen=fd.open})}
 if(!document.getElementById('sprog')){const p=document.createElement('div');p.id='sprog';document.body.appendChild(p);window.addEventListener('scroll',()=>{const h=document.documentElement;p.style.width=(scrollY/Math.max(1,h.scrollHeight-innerHeight)*100)+'%'},{passive:true})}
 tickCd();if(anim&&location.hash.startsWith('#cert-'))setTimeout(()=>burst(innerWidth/2,200),500);
 applyLang()}
document.addEventListener('click',e=>{
 const b=e.target.closest('button,.btn,.cta,.pill,a.btn');if(b&&!document.documentElement.classList.contains('rm')&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const r=b.getBoundingClientRect(),s=document.createElement('span');s.className='rip';const d=Math.max(r.width,r.height)*1.6;s.style.cssText=`width:${d}px;height:${d}px;left:${e.clientX-r.left-d/2}px;top:${e.clientY-r.top-d/2}px`;if(getComputedStyle(b).position==='static')b.style.position='relative';b.classList.add('hasrip');b.appendChild(s);setTimeout(()=>s.remove(),600)}
 const t=e.target.closest('[data-gal-go],[data-gal-to],[data-aicheck],[data-rvf],[data-accf],[data-closefilter],[data-finish],[data-addcv],[data-certpdf],[data-certcopy],[data-hr],[data-mslot],[data-mbook],#coRev,#langBtn,#replayIntro');if(!t)return;
 if(t.dataset.galGo){const g=t.closest('[data-gal]');galSet(g,+g.dataset.i+ +t.dataset.galGo);clearInterval(galT)}
 else if(t.dataset.galTo!==undefined){const g=t.closest('[data-gal]');galSet(g,+t.dataset.galTo);clearInterval(galT)}
 else if(t.dataset.aicheck)openAI(+t.dataset.aicheck);
 else if(t.dataset.rvf){rvf=t.dataset.rvf;render()}
 else if(t.dataset.accf){const k=t.dataset.accf;S.f.acc=S.f.acc.includes(k)?S.f.acc.filter(x=>x!==k):[...S.f.acc,k];render()}
 else if(t.dataset.closefilter!==undefined){S.fsOpen=false;render();window.scrollTo({top:0,behavior:'smooth'})}
 else if(t.dataset.mslot){document.querySelectorAll('[data-mslot^="'+t.dataset.mslot.split('|')[0]+'|"]').forEach(x=>x.setAttribute('aria-pressed',x===t))}
 else if(t.dataset.mbook!==undefined){const p=document.querySelector('[data-mslot^="'+t.dataset.mbook+'|"][aria-pressed="true"]');toast(p?'จองเวลา '+p.textContent+' แล้ว (เดโม)':'เลือกเวลาก่อนนะ')}

 else if(t.id==='langBtn'){S.lang=S.lang==='en'?'th':'en';store.set('lang',S.lang);applyLang()}
 else if(t.dataset.finish!==undefined){const a=S.apps[+t.dataset.finish];a.status='done';a.tl.push('ฝึกงานครบ 12 สัปดาห์ · 480 ชั่วโมง','ออกใบรับรองการฝึกงาน · 13 พ.ย. 2569');save();location.hash='cert-'+t.dataset.finish;toast('พี่เลี้ยงประเมินแล้ว · ออกใบรับรองให้อัตโนมัติ')}
 else if(t.dataset.addcv!==undefined){S.resume.cert=true;save();render();toast('เพิ่มใบรับรองลงเรซูเม่แล้ว')}
 else if(t.dataset.certpdf!==undefined)toast('ในแอปจริงจะบันทึกใบรับรองเป็น PDF ขนาด A4 · เดโมนี้ยังไม่มีการพิมพ์')
 else if(t.dataset.certcopy!==undefined){try{navigator.clipboard.writeText('maadoo.pages.dev/verify/'+CERT.no)}catch(x){}t.innerHTML=ico('doc')+' คัดลอกแล้ว';toast('คัดลอกลิงก์ตรวจสอบใบรับรองแล้ว (เดโม)')}
 else if(t.dataset.hr!==undefined)toast('จองบริการ'+t.dataset.hr+'แล้ว (เดโม ไม่มีการตัดเงิน)')
 });
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.ff==='fast'){S.f.fast=t.checked;render();live('อัปเดตผลลัพธ์แล้ว')}
 if(t.dataset.pay!==undefined){S.f.minPay=+t.value;render();live('ค่าตอบแทนขั้นต่ำ '+t.value)}});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.pay!==undefined){const v=$('#payV');if(v)v.textContent=+t.value?'฿'+(+t.value).toLocaleString():'ทั้งหมด'}});
window.addEventListener('scroll',()=>{document.querySelector('header.top').classList.toggle('sc',scrollY>8)},{passive:true});

/* ===== landing + sign-in gate ===== */
const LAND_WORDS=['รีวิวจริง','บรรยากาศ','ค่าตอบแทน','พี่เลี้ยง','ที่ทำงานที่รองรับ'];
let SCR='กขคงจฉชซญดตถทธนบปผพฟภมยรลวศษสหอฮะาิีึืุูเแโใไ';
function pcard(o,i){const P=[[-2,12,-6,230,16],[12,50,5,200,26],[2,80,-3,220,12],[ -2,10,6,220,18],[10,47,-5,210,24],[-2,77,4,230,14],[30,84,3,170,30],[28,86,-4,170,20]][i];const right=i>=3&&i<6||i===7;
 const pos=right?`right:${P[0]}%`:`left:${P[0]}%`;
 const ic=EI[o.e]||'spark';
 return `<div class="pc pc${i}" style="${pos};top:${P[1]}%;width:${P[3]}px;--dep:${P[4]}"><div class="pci" style="--r:${P[2]}deg;animation-delay:${-i*1.3}s"><div class="pcv">${(PH[phKey(o)]&&PH[phKey(o)][0])||(DPH[phKey(o)]||[])[0]?`<div class="sl"><img src="${(PH[phKey(o)]&&PH[phKey(o)][0])||DPH[phKey(o)][0]}" alt=""></div>`:`<div class="sl s${i%3}" style="--c:var(${o.c})"><b class="bl bl1"></b><b class="bl bl2"></b>${ico(ic)}</div>`}</div><div class="pcb"><span class="av" style="background:var(${o.c})">${o.ini}</span><div><b>${esc(o.who||o.co)}</b><small>${esc((o.t||'').slice(0,28))}</small></div><i class="on"></i></div></div></div>`}
function landHTML(){const cards=[JOBS[0],GIGS[0],JOBS[2],JOBS[1],GIGS[3],JOBS[4],GIGS[1],JOBS[7]];
 const feats=[['clock','ตามใบสมัครให้ใน 14 วัน','บริษัทเงียบ เราเตือน ไม่ตอบ คืน Slot ให้อัตโนมัติ'],['star','รีวิวจากคนเคยทำจริง','บรรยากาศ พี่เลี้ยง ค่าตอบแทนตรงประกาศ ก่อนตัดสินใจสมัคร'],['access','รองรับคนพิการ','กรองงานตามทางลาด ตัวช่วยอ่านจอ ล่ามภาษามือ และมาตรา 33'],['spark','AI ตรวจความเหมาะสม','เทียบทักษะกับงาน บอกสิ่งที่ยังขาด ไม่ตัดใครออก'],['doc','ใบรับรองการฝึกงาน','ฝึกครบ พี่เลี้ยงประเมิน รับใบรับรองที่ตรวจสอบได้'],['shield','ฟรีแลนซ์จ่ายผ่านระบบกลาง','เงินถึงนักศึกษาเมื่อคุณกดอนุมัติงาน']];
 const steps=[['search','ดูก่อน','ค้นงาน ดูรีวิว และการรองรับ'],['doc','สมัครด้วย Slot','มี 3 Slot ฟรี ส่งเรซูเม่ในคลิกเดียว'],['clock','ตามผล 14 วัน','เราเตือนบริษัทและคืน Slot ให้'],['star','ได้ใบรับรอง','ฝึกครบ รับใบรับรองพร้อมผลประเมิน']];
 return `<nav class="lnav" id="lnav"><a class="llogo" href="#" onclick="return false"><img src="${document.querySelector('.logo img').src}" alt="">Maadoo</a><span style="flex:1"></span><button class="lbtn out lang" id="lLangBtn" aria-label="เปลี่ยนภาษา ไทย/อังกฤษ">TH | EN</button><button class="lbtn ghost" data-auth="in">เข้าสู่ระบบ</button><button class="lbtn dark" data-auth="up">สมัครสมาชิก</button></nav>
 <section class="lhero" id="lhero">${cards.map(pcard).join('')}
  <div class="lcore"><span class="lkick">${ico('spark')} ก่อนไปทำงาน มาดูก่อน</span><h1 class="lh1">ดูให้ชัวร์<br>ก่อนไปทำงาน<br><span class="lrot" id="lrot" aria-live="off">${LAND_WORDS[0]}</span></h1><p class="lsub">ฝึกงาน งานแรก และพาร์ทไทม์ พร้อมรีวิวจริงจากคนเคยทำ ข้อมูลการรองรับคนพิการ และตามใบสมัครให้ถึงที่สุด</p>
  <div class="lcd" aria-label="นับถอยหลังปิดรับสมัคร"><p class="lcdt">ฝึกงาน Digital Marketing ปิดรับสมัครใน</p><div class="lcdw">${['d','h','m','s'].map((k,i)=>`<div class="tile"><b id="cd_${k}"><span>00</span></b><small>${['วัน','ชั่วโมง','นาที','วินาที'][i]}</small></div>`).join('')}</div></div>
  <div class="lcta"><button class="lbtn dark big" data-auth="up">เริ่มกันเลย</button><button class="lbtn out big" id="lPreview">ดูตัวอย่างในเว็บ</button></div></div>
  <button class="lscroll" id="lDown" aria-label="เลื่อนลงดูตัวอย่าง"><span>เลื่อนลง</span>${ico('chart','lchev')}<i></i></button></section>
 <div class="lmq" aria-hidden="true"><div class="lmqt">${[0,1,2,3,4,5].map(()=>CATS.map(c=>`<span>${ico(CI[c[2]])} ${c[1]}</span>`).join('')).join('')}</div></div>
 <section class="lsec" id="lprev"><h2 class="lh2 lr">เห็นภาพรวมก่อนเข้าใช้งาน</h2><p class="lp lr">ตัวอย่างหน้าตาจริงของ Maadoo เข้าสู่ระบบเพื่อกดดูรายละเอียดและสมัคร</p>
  <div class="mock lr"><div class="mockbar"><i></i><i></i><i></i><span>maadoo.pages.dev</span></div><div class="mockg">${[JOBS[0],JOBS[1],JOBS[2],JOBS[3],JOBS[4],JOBS[5]].map(j=>`<button class="mc" data-auth="in" aria-label="เข้าสู่ระบบเพื่อดู ${esc(j.t)}"><div class="mcv"><div class="sl s0" style="--c:var(${j.c})">${(DPH[phKey(j)]||[])[0]?`<img src="${DPH[phKey(j)][0]}" alt="" loading="lazy">`:`<b class="bl bl1"></b><b class="bl bl2"></b>${ico(EI[j.e]||'spark')}`}</div></div><div class="mcb"><small>${j.co}</small><b>${j.t}</b><span><em>★ ${j.r}</em> ${j.pay}</span></div></button>`).join('')}<div class="mlock">${ico('shield')}<b>เข้าสู่ระบบเพื่อดูงานทั้งหมด</b><button class="lbtn dark" data-auth="in">เข้าสู่ระบบ</button></div></div></div></section>
 <section class="lsec"><h2 class="lh2 lr">ใช้งานอย่างไร</h2><div class="lsteps">${steps.map((s,i)=>`<div class="lstep lr" style="--d:${i*120}ms"><span class="lnum">${i+1}</span><span class="cic big">${ico(s[0])}</span><b>${s[1]}</b><small>${s[2]}</small></div>`).join('')}<div class="lline"><i></i></div></div></section>
 <section class="lsec lstat"><div class="lstats">${[[14,' วัน','ตามใบสมัครให้'],[3,' Slot','สมัครฟรีพร้อมกัน'],[6,' แบบ','การรองรับในที่ทำงาน'],[4,' ขั้น','ทำงานฟรีแลนซ์ผ่านระบบกลาง']].map(s=>`<div class="lr"><b data-count="${s[0]}">0</b><span>${s[1]}</span><small>${s[2]}</small></div>`).join('')}</div></section>
 <section class="lsec"><h2 class="lh2 lr">ทำไมต้อง Maadoo</h2><div class="lfeat">${feats.map((f,i)=>`<article class="lf lr" style="--d:${(i%3)*100}ms"><span class="cic big">${ico(f[0])}</span><b>${f[1]}</b><p>${f[2]}</p></article>`).join('')}</div></section>
 <section class="lfinal lr"><h2>พร้อมดูก่อนไปทำงานหรือยัง</h2><p>เข้าสู่ระบบแล้วเริ่มค้นงานได้ทันที (เดโมนี้ใช้ข้อมูลสมมติ)</p><button class="lbtn yel big" data-auth="up">เริ่มกันเลย</button></section>
 <footer class="lfoot">Maadoo · ก่อนไปทำงาน มาดูก่อน · เดโมสำหรับ GEN354</footer>`}
function authHTML(mode){const up=mode==='up';return `<div class="lov" data-lov><form class="lmodal" id="authF" role="dialog" aria-modal="true" aria-labelledby="authT" novalidate><button type="button" class="lx" data-authx aria-label="ปิด">×</button><div class="ltabs" role="tablist"><button type="button" role="tab" data-auth="in" aria-selected="${!up}">เข้าสู่ระบบ</button><button type="button" role="tab" data-auth="up" aria-selected="${up}">สมัครสมาชิก</button></div>
 <h2 id="authT">${up?'สร้างบัญชีฟรี':'ยินดีต้อนรับกลับ'}</h2><p class="lp" style="margin:0 0 4px">${up?'ใช้เวลาไม่ถึงนาที ได้ 3 Slot สมัครงานฟรี':'เข้าสู่ระบบเพื่อใช้งาน Maadoo'}</p>
 ${up?'<div class="lfld"><label for="auN">ชื่อ-นามสกุล</label><input id="auN" autocomplete="name" placeholder="เช่น ณัฐชา ใจดี"></div>':''}
 <div class="lfld"><label for="auE">อีเมล</label><input id="auE" type="email" autocomplete="email" placeholder="you@example.com"></div>
 <div class="lfld"><label for="auP">รหัสผ่าน</label><div class="pw"><input id="auP" type="password" autocomplete="${up?'new-password':'current-password'}" placeholder="อย่างน้อย 6 ตัวอักษร"><button type="button" id="auShow" aria-pressed="false">แสดง</button></div></div>
 <p class="lerr" id="auErr" role="alert" hidden></p>
 <button class="lbtn dark big" style="width:100%" id="auGo">${up?'สมัครสมาชิก':'เข้าสู่ระบบ'}</button>
 <div class="lor"><span>หรือ</span></div><button type="button" class="lbtn out big" style="width:100%" id="auDemo">ใช้บัญชีตัวอย่าง (ณัฐชา ใจดี)</button>
 <p class="lnote">เดโมเท่านั้น: ข้อมูลที่กรอกไม่ถูกส่งไปที่ใด และรหัสผ่านไม่ถูกเก็บ</p></form></div>`}
function setAuth(u){S.auth=u;store.set('auth',u)}
function gateOn(){document.body.classList.add('locked');['header.top','main','footer','#bnav'].forEach(s=>{const e=document.querySelector(s);if(e)e.setAttribute('inert','')})}
function gateOff(){document.body.classList.remove('locked');['header.top','main','footer','#bnav'].forEach(s=>{const e=document.querySelector(s);if(e)e.removeAttribute('inert')})}
function scramble(el,txt){if(matchMedia('(prefers-reduced-motion: reduce)').matches||S.a11y.rm){el.textContent=txt;return}let f=0;const n=14;const id=setInterval(()=>{f++;el.textContent=[...txt].map((c,i)=>f/n>(i+1)/txt.length+.15?c:SCR[Math.random()*SCR.length|0]).join('');if(f>=n+6){clearInterval(id);el.textContent=txt}},45)}
function openAuth(mode){const L=$('#land');if(!L)return;let o=$('#authHost');if(!o){o=document.createElement('div');o.id='authHost';L.appendChild(o)}
 o.innerHTML=authHTML(mode);L.classList.add('lmodalopen');const f=$('#authF');setTimeout(()=>f.querySelector('input').focus(),50)}
function closeAuth(){const o=$('#authHost');if(o)o.innerHTML='';const L=$('#land');if(L){L.classList.remove('lmodalopen');const b=L.querySelector('[data-auth="up"]');b&&b.focus()}}
function finishAuth(u){const g=$('#auGo');g.disabled=true;g.innerHTML='<span class="spin" style="width:18px;height:18px;border-width:2px;display:inline-block;vertical-align:-3px"></span> กำลังเข้าสู่ระบบ…';
 setTimeout(()=>{setAuth(u);if(u.name&&u.name!=='ณัฐชา ใจดี'&&!store.get('resumeNamed',0)){S.resume.name=u.name;store.set('resumeNamed',1);save()}unlock(true)},700)}
function unlock(anim){const L=$('#land');gateOff();document.body.classList.remove('noscroll');if(!L){render(true);return}
 L.classList.add('leave');setTimeout(()=>{L.remove();window.scrollTo(0,0);render(true);toast('ยินดีต้อนรับ '+(S.auth&&S.auth.name?S.auth.name.split(' ')[0]:'')+' · พร้อมดูงานแล้ว')},anim?900:0)}
function logout(){S.auth=null;try{localStorage.removeItem('maadoo-demo-auth')}catch(e){}showLand()}
function showLand(){const old=$('#land');if(old)old.remove();gateOn();document.body.classList.add('noscroll');
 const L=document.createElement('div');L.id='land';L.setAttribute('role','region');L.setAttribute('aria-label','หน้าต้อนรับ Maadoo');L.innerHTML=landHTML();document.body.appendChild(L);
 /* rotating headline */
 let wi=0;const rot=$('#lrot');const rt=setInterval(()=>{if(!document.body.contains(L)){clearInterval(rt);return}wi=(wi+1)%LAND_WORDS.length;scramble(rot,LAND_WORDS[wi])},2600);
 /* countdown with flip */
 const T=new Date('2026-12-12T23:59:59').getTime();const cd=()=>{let d=Math.max(0,T-Date.now());const v={d:Math.floor(d/864e5),h:Math.floor(d%864e5/36e5),m:Math.floor(d%36e5/6e4),s:Math.floor(d%6e4/1e3)};for(const k in v){const el=$('#cd_'+k);if(!el)return;const s=String(v[k]).padStart(2,'0');if(el.dataset.v!==s){el.dataset.v=s;el.innerHTML=`<span class="flip">${s}</span>`}}};cd();const ct=setInterval(()=>{if(!document.body.contains(L)){clearInterval(ct);return}cd()},1000);
 /* parallax */
 const hero=$('#lhero');L.addEventListener('mousemove',e=>{if(S.a11y.rm)return;hero.style.setProperty('--mx',(e.clientX/innerWidth-.5).toFixed(3));hero.style.setProperty('--my',(e.clientY/innerHeight-.5).toFixed(3))});
 /* reveal + counters + scroll effects */
 const io2=new IntersectionObserver(es=>es.forEach(x=>{if(!x.isIntersecting)return;const el=x.target;el.classList.add('in');io2.unobserve(el);el.querySelectorAll('[data-count]').forEach(c=>{const n=+c.dataset.count;let k=0;const id=setInterval(()=>{k++;c.textContent=Math.round(n*Math.min(1,k/22));if(k>=22)clearInterval(id)},40)});if(el.matches('[data-count]')){}}),{root:L,threshold:.15});
 L.querySelectorAll('.lr').forEach(e=>io2.observe(e));
 const mock=L.querySelector('.mock'),nav=$('#lnav');let tick=false,lastSc=null,lastT='',stm=0;const upd=()=>{tick=false;const sc=L.scrollTop>30;if(sc!==lastSc){lastSc=sc;nav.classList.toggle('sc',sc)}if(mock){const r=mock.getBoundingClientRect();if(r.top<innerHeight&&r.bottom>0){const v=Math.min(1,Math.max(0,1-(r.top-innerHeight*.25)/(innerHeight*.7))).toFixed(2);if(v!==lastT){lastT=v;mock.style.setProperty('--t',v)}}}};const onS=()=>{if(!L.classList.contains('scr'))L.classList.add('scr');clearTimeout(stm);stm=setTimeout(()=>L.classList.remove('scr'),160);if(!tick){tick=true;requestAnimationFrame(upd)}};L.addEventListener('scroll',onS,{passive:true});upd();
 $('#lPreview').addEventListener('click',()=>$('#lprev').scrollIntoView({behavior:'smooth'}));$('#lDown').addEventListener('click',()=>$('#lprev').scrollIntoView({behavior:'smooth'}));
 L.addEventListener('click',e=>{const t=e.target.closest('[data-auth],[data-authx]');if(t){if(t.dataset.authx!==undefined)closeAuth();else openAuth(t.dataset.auth);return}
  if(e.target.matches('[data-lov]'))closeAuth();
  if(e.target.id==='auShow'){const p=$('#auP');const s=p.type==='password';p.type=s?'text':'password';e.target.textContent=s?'ซ่อน':'แสดง';e.target.setAttribute('aria-pressed',s)}
  if(e.target.id==='auDemo'){e.preventDefault();finishAuth({name:'ณัฐชา ใจดี',email:'natcha@example.com'})}});
 L.addEventListener('submit',e=>{e.preventDefault();if(e.target.id!=='authF')return;const up=!!$('#auN');const n=up?$('#auN').value.trim():'',m=$('#auE').value.trim(),p=$('#auP').value;const er=$('#auErr');
  const bad=(msg,id)=>{er.textContent=msg;er.hidden=false;const f=$('#authF');f.classList.remove('shake');void f.offsetWidth;f.classList.add('shake');$(id).focus()};
  if(up&&n.length<2)return bad('กรอกชื่อ-นามสกุลก่อนนะ','#auN');if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(m))return bad('อีเมลไม่ถูกต้อง ลองใหม่อีกครั้ง','#auE');if(p.length<6)return bad('รหัสผ่านต้องมีอย่างน้อย 6 ตัวอักษร','#auP');
  finishAuth({name:n||m.split('@')[0],email:m})});
 L.addEventListener('keydown',e=>{if(e.key==='Escape')closeAuth();if(e.key==='Tab'&&$('#authF')){const els=[...$('#authF').querySelectorAll('button,input')].filter(x=>!x.disabled);if(!els.length)return;const f=els[0],l=els[els.length-1];if(e.shiftKey&&document.activeElement===f){e.preventDefault();l.focus()}else if(!e.shiftKey&&document.activeElement===l){e.preventDefault();f.focus()}}})}
function initGate(){if(S.auth){gateOff();return}showLand()}
document.addEventListener('click',e=>{if(e.target.closest('#logoutBtn,#logoutTop'))logout()});

S.lang=store.get('lang','th');S.auth=store.get('auth',null);S.fsOpen=false;
applyA11y();render(false);initGate();

(function(){function pick(e,p){const T=e.target;if(!T||!T.closest)return null;let v=T.closest('.cv,.gview');if(!v){const c=T.closest('.card');v=c&&c.querySelector('.cv')}if(!v)return null;const r=v.getBoundingClientRect();return(p.clientY>=r.top&&p.clientY<=r.bottom&&p.clientX>=r.left&&p.clientX<=r.right)?v:null}
function scrub(e){const p=e.touches?e.touches[0]:e;const v=pick(e,p);if(!v)return;const sl=v.querySelector('.slides');if(!sl)return;const n=sl.querySelectorAll('.sl').length;if(n<2)return;const r=v.getBoundingClientRect();const k=Math.max(0,Math.min(n-1,Math.floor((p.clientX-r.left)/r.width*n)));const g=v.closest('[data-gal]');
 if(g){if(+g.dataset.i!==k)galSet(g,k);return}
 if(sl.dataset.k!==String(k)){sl.dataset.k=k;sl.style.setProperty('--gi',k);v.querySelectorAll('.dots i').forEach((d,j)=>d.classList.toggle('on',j===k))}}
function back(e){const T=e.target;if(!T||!T.closest)return;const c=T.closest('.card');const v=c&&c.querySelector('.cv');if(!v)return;if(e.relatedTarget&&c.contains(e.relatedTarget))return;const sl=v.querySelector('.slides');if(!sl)return;sl.dataset.k=0;sl.style.setProperty('--gi',0);v.querySelectorAll('.dots i').forEach((d,j)=>d.classList.toggle('on',j===0))}
document.addEventListener('mousemove',scrub,{passive:true});document.addEventListener('touchmove',scrub,{passive:true});document.addEventListener('mouseout',back);
new MutationObserver(()=>{document.querySelectorAll('.dots i:first-child').forEach(d=>{const p=d.parentNode;if(!p.querySelector('.on'))d.classList.add('on')})}).observe(document.body,{childList:true,subtree:true})})();

(function(){const oa=V.apps;
 V.apps=()=>{const n=activeApps();const st0=a=>({wait:['รอบริษัทตอบ · วันที่ '+a.day+' จาก 14','o','var(--orange)'],invite:['เชิญสัมภาษณ์ · เลือกเวลา','','var(--blue)'],booked:['นัดสัมภาษณ์แล้ว · '+(a.picked||''),'g','var(--green)'],withdrawn:['ถอนใบสมัครแล้ว','r','var(--muted)'],train:['กำลังฝึกงาน','p','var(--purple)'],done:['ฝึกงานเสร็จ · ได้ใบรับรอง','g','var(--green)']})[a.status];
  const act=S.apps.filter(a=>['wait','invite','booked'].includes(a.status));
  const tiles=Array.from({length:S.slotLimit},(_,k)=>{const a=act[k];if(!a)return `<a class="slt add" href="#jobs" aria-label="เพิ่มใบสมัคร ใช้ Slot ว่าง" title="ใช้ Slot ว่างสมัครงานใหม่">+</a>`;const j=job(a.job);const im=(DPH[phKey(j)]||[])[0];return `<a class="slt" href="#job-${j.id}" title="${esc(j.co)}" style="--c:var(${j.c})">${im?`<img src="${im}" alt="">`:`<span class="av" style="background:var(${j.c})">${j.ini||''}</span>`}<small>${esc(j.co.split(' ')[0])}</small></a>`}).join('');
  const rows=S.apps.length?S.apps.map((a,i)=>{const j=job(a.job);const st=st0(a);const im=(DPH[phKey(j)]||[])[0];
   const body=oa_one(a,i,j);
   return `<details class="appx" style="--bc:${st[2]}" ${S.appOpen===i?'open':''}><summary data-ap="${i}"><span class="ath" style="background:var(${j.c})">${im?`<img src="${im}" alt="">`:(j.ini||'')}</span><span class="atx"><b>${esc(j.co)}</b><small>${esc(j.t)}</small></span><span class="chip ${st[1]}">${st[0]}</span><span class="chev" aria-hidden="true">›</span></summary><div class="apb">${body}</div></details>`}).join(''):'<div class="box empty">ยังไม่มีใบสมัคร · <a href="#jobs">ไปหางาน</a></div>';
  return `<div class="sec" style="margin-top:0"><h1 style="font-size:1.5rem">ใบสมัครของฉัน</h1></div>
 <div class="box" style="margin-bottom:14px"><div style="display:flex;justify-content:space-between"><b>Slot สมัครที่ใช้อยู่</b><b>${n} / ${S.slotLimit}</b></div><div class="slotrow" aria-label="Slot ทั้งหมด">${tiles}</div><p class="meta" style="margin:8px 0 0">กดรูปบริษัทเพื่อดูงาน · ช่อง “+” คือ Slot ว่าง · Slot คืนเมื่อบริษัทตอบ หรือเมื่อคุณถอนใบสมัคร</p></div>
 <div>${rows}</div>`};
 function oa_one(a,i,j){const st=({wait:'o'})[a.status];
  return `<h2 style="font-size:1rem;margin:10px 0 2px"><a href="#job-${j.id}">${j.t}</a></h2>
 <ol class="timeline" aria-label="ไทม์ไลน์">${a.tl.map(x=>`<li>✅ ${esc(x)}</li>`).join('')}${a.status==='wait'||a.status==='invite'?`<li>⏳ ผลสุดท้าย · เหลือเวลา <b class="cdl" data-cd="${DUE0+(14-(a.day||0))*864e5}"></b></li>`:''}</ol>
 ${a.status==='invite'?`<fieldset style="border:0;padding:0;margin:0"><legend style="font-weight:700;color:var(--ink);margin-bottom:6px">เลือกเวลาสัมภาษณ์ (ออนไลน์ · มีคำบรรยายสด)</legend><div class="chips" style="gap:8px">${a.slots.map(s=>`<button class="pill" data-slot="${i}" data-v="${s}">${s}</button>`).join('')}</div></fieldset>`:''}
 ${trainBlock(a,i)}${!['withdrawn','train','done'].includes(a.status)?`<div style="margin-top:8px"><button class="btn d" data-withdraw="${i}">ถอนใบสมัคร</button></div>`:''}<p style="margin:8px 0 0"><a href="#job-${j.id}">ดูรายละเอียดงาน ›</a></p>`}
 const or=V.resume;
 V.resume=()=>{const h=or();const sc=rScore(S.resume);const k=h.indexOf('<div class="rb">');if(k<0)return h;
  return h.slice(0,k)+`<details class="rsmd" ${S.rOpen?'open':''}><summary data-rs><span class="cic">${ico('doc')}</span><span class="rsb"><b>เรซูเม่ของฉัน · ครบ <span id="rPct2">${sc}</span>%</b><i><u style="width:${sc}%"></u></i></span><span class="rsgo">${S.rOpen?'ซ่อน':'แก้ไข / ดูตัวอย่าง'}</span></summary>`+h.slice(k)+`</details>`};
 document.addEventListener('click',e=>{const s=e.target.closest&&e.target.closest('summary[data-ap],summary[data-rs]');if(s){if(s.dataset.ap!==undefined){const i=+s.dataset.ap;S.appOpen=S.appOpen===i?-1:i}else{S.rOpen=!S.rOpen;setTimeout(()=>{const g=s.querySelector('.rsgo');if(g)g.textContent=S.rOpen?'ซ่อน':'แก้ไข / ดูตัวอย่าง'},0)}return}
  const f=e.target;if(f.classList&&f.classList.contains('ffold')&&f.open&&innerWidth<=860){S.fsOpen=false;render()}});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){const f=document.querySelector('details.ffold[open]');if(f&&innerWidth<=860){S.fsOpen=false;render()}}});
})();

(function(){
 S.slotLimit=store.get('slotlimit',S.slotLimit);
 let NR=store.get('nread',null);let NF='all';
 let NEEDS=store.get('needs',['ramp','sr']);let SHARE=store.get('needshare',false);
 let BPICK=store.get('badgepick','');let SENT=store.get('certsent',[]);
 const nick=()=>(S.resume.name||'ผู้ใช้').split(' ')[0];
 function NL(){const out=[];
  S.apps.forEach((a,i)=>{const j=job(a.job);
   if(a.status==='invite')out.push({id:'a'+i+'inv',i,j,txt:'บริษัทเชิญสัมภาษณ์ · ยังไม่ได้เลือกเวลา',dt:'ต้องทำ',kind:'สัมภาษณ์',ic:'user',act:1});
   a.tl.slice().reverse().forEach((tx,k0)=>{const k=a.tl.length-1-k0;const p=tx.split(' · ');let kind='ใบสมัคร',ic='doc';
    if(/เตือน/.test(tx)){kind='ติดตามโดย Maadoo';ic='clock'}else if(/เปิดดู/.test(tx)){kind='บริษัทเปิดดู';ic='eye'}else if(/เชิญ|สัมภาษณ์/.test(tx)){kind='สัมภาษณ์';ic='user'}else if(/ฝึกงาน|ประเมิน|ใบรับรอง/.test(tx)){kind='ผลและการฝึกงาน';ic='flask'}
    out.push({id:'a'+i+'t'+k,i,j,txt:p[0],dt:p[1]||'',kind,ic,proof:kind==='ติดตามโดย Maadoo'?'MJ-FU-'+(2040+i*7+k):''})});
  });
  SENT.forEach((s,k)=>{out.unshift({id:'s'+k,i:-1,j:job(s.job),txt:'ส่งใบรับรองการฝึกงานให้บริษัทแล้ว',dt:s.d,kind:'ผลและการฝึกงาน',ic:'shield'})});
  return out}
 if(NR===null){NR=NL().map(x=>x.id).filter(id=>id!=='a1inv'&&id!=='a0t2')}
 const unread=()=>NL().filter(x=>!NR.includes(x.id)).length;
 function updBell(){const c=unread();const b=document.querySelector('#bellBtn');if(!b)return;const d=b.querySelector('.dot');if(d){d.textContent=c;d.style.display=c?'':'none'}b.setAttribute('aria-label','การแจ้งเตือน '+c+' รายการ')}
 function tabs(a){const T=[['apps','ใบสมัคร'],['notif','แจ้งเตือน'],['resume','เรซูเม่'],['badges','ใบรับรอง & ป้าย'],['needs','ความต้องการของฉัน']];const u=unread();
  return `<nav class="metabs" aria-label="เมนูของฉัน">${T.map(x=>`<a href="#${x[0]}" ${x[0]===a?'aria-current="page"':''}>${x[1]}${x[0]==='notif'&&u?`<span class="nb">${u}</span>`:''}</a>`).join('')}</nav>`}
 function head(){const bd=BD().find(b=>b.id===BPICK&&b.earned);return `<div class="mehead"><span class="meav" aria-hidden="true">${esc(nick()).slice(0,1)}</span><div><b>${esc(nick())}</b>${bd?`<span class="bdg">${ico('shield')} ${esc(bd.t)}</span>`:''}<small>${esc(S.resume.role||'')}</small></div></div>`}
 const oa=V.apps,or=V.resume;
 V.apps=()=>head()+tabs('apps')+oa();
 V.resume=()=>head()+tabs('resume')+or();
 V.notif=()=>{const all=NL();const F={all:()=>true,follow:x=>x.kind==='ติดตามโดย Maadoo',int:x=>x.kind==='สัมภาษณ์',res:x=>x.kind==='ผลและการฝึกงาน'};const L=all.filter(F[NF]);const u=unread();
  const fl=[['all','ทั้งหมด'],['follow','Maadoo ติดตามให้'],['int','สัมภาษณ์'],['res','ผลและการฝึกงาน']];
  return head()+tabs('notif')+`<div class="sec" style="margin-top:0"><h1 style="font-size:1.5rem">การแจ้งเตือน</h1>${u?`<button class="btn" data-nread>ทำเครื่องหมายว่าอ่านแล้วทั้งหมด (${u})</button>`:'<span class="chip g">อ่านครบแล้ว</span>'}</div>
  <p class="meta" style="margin:-4px 0 10px">รู้สถานะทุกอย่างในแอปนี้ ไม่ต้องรออีเมลหรือโทรศัพท์ · เมื่อบริษัทเงียบ Maadoo ติดตามให้และลงบันทึกไว้ตรงนี้</p>
  <div class="nfilt" role="group" aria-label="กรองแจ้งเตือน">${fl.map(f=>`<button class="pill" data-nf="${f[0]}" aria-pressed="${NF===f[0]}">${f[1]}</button>`).join('')}</div>
  ${L.length?L.map(x=>`<a class="nitem ${NR.includes(x.id)?'':'un'} ${x.act?'act':''}" href="#apps" data-nopen="${x.id}"><span class="cic">${ico(x.ic)}</span><div style="flex:1;min-width:0"><b>${esc(x.j?x.j.co:'')} · ${esc(x.txt)}</b><small>${esc(x.kind)}${x.dt?' · '+esc(x.dt):''}</small>${x.proof?`<small style="display:block;margin-top:2px">อ้างอิงการติดตาม ${x.proof} · ในระบบจริงเก็บสำเนาอีเมลเป็นหลักฐาน (เดโมจำลอง)</small>`:''}</div>${NR.includes(x.id)?'':'<span class="nd" aria-label="ยังไม่อ่าน"></span>'}</a>`).join(''):'<div class="box empty">ไม่มีรายการในหมวดนี้</div>'}
  <p class="notice">การแจ้งเตือนเป็นข้อมูลตัวอย่างสำหรับเดโม</p>`};
 function BD(){const b=[];S.apps.forEach((a,i)=>{if(a.status==='done'){const j=job(a.job);b.push({id:'int'+i,t:'ผ่านฝึกงาน '+j.co,s:'ใบรับรองเลขที่ '+CERT.no,earned:true,c:'--c3',ic:'shield'})}});
  b.push({id:'xl',t:'Excel พื้นฐาน',s:'คอร์สพื้นฐานฟรี · เรียนจบแล้ว',earned:true,c:'--c1',ic:'chart'},{id:'cv',t:'เรซูเม่ครบ 100%',s:rScore(S.resume)>=100?'เติมครบทุกช่องแล้ว':'เติมให้ครบเพื่อรับป้าย',earned:rScore(S.resume)>=100,c:'--c2',ic:'doc'},{id:'dm',t:'Digital Marketing Experience',s:'คอร์สเฉพาะทาง · ยังไม่ได้เรียน',earned:false,c:'--c4',ic:'mega'},{id:'gd',t:'Graphic Design Experience',s:'คอร์สเฉพาะทาง · ยังไม่ได้เรียน',earned:false,c:'--c5',ic:'palette'});return b}
 V.badges=()=>{const B=BD();const done=S.apps.map((a,i)=>[a,i]).filter(x=>x[0].status==='done');const tr=S.apps.map((a,i)=>[a,i]).filter(x=>x[0].status==='train');
  return head()+tabs('badges')+`<div class="sec" style="margin-top:0"><h1 style="font-size:1.5rem">ใบรับรองและป้าย</h1></div>
  <p class="meta" style="margin:-4px 0 10px">เรียนทักษะหรือฝึกงานจบแล้วได้ป้ายแสดงข้างชื่อ และส่งใบรับรองให้บริษัทที่สมัครอยู่ได้ในคลิกเดียว</p>
  <h2 style="font-size:1.05rem">ป้ายของฉัน</h2><div class="bgrid">${B.map(b=>`<div class="bcard ${b.earned?'':'lock'}" style="--c:var(${b.c})"><div class="bc" aria-hidden="true">${ico(b.ic)}</div><b>${esc(b.t)}</b><small>${esc(b.s)}</small>${b.earned?`<button class="pill bpick" data-bpick="${b.id}" aria-pressed="${BPICK===b.id}">${BPICK===b.id?'แสดงข้างชื่ออยู่':'แสดงข้างชื่อ'}</button>`:`<a class="pill bpick" href="#programs">ไปเรียน</a>`}</div>`).join('')}</div>
  <h2 style="font-size:1.05rem;margin-top:18px">ใบรับรอง</h2>
  ${done.length?done.map(([a,i])=>{const j=job(a.job);return `<div class="box" style="margin-bottom:10px"><b>${esc(j.t)}</b><div class="meta">${esc(j.co)} · เลขที่ ${CERT.no} · ผลประเมิน ${CERT.score}/5</div><div style="display:flex;gap:8px;margin-top:8px;flex-wrap:wrap"><a class="btn y" href="#cert-${i}">ดูใบรับรอง</a><button class="btn" data-certsend="${i}">ส่งให้บริษัทที่สมัครอยู่</button></div></div>`}).join(''):`<div class="box">${tr.length?`<b>ฝึกงานที่ ${esc(job(tr[0][0].job).co)} ใกล้จบแล้ว</b><div class="meta" style="margin:4px 0 8px">ครบตามแผน 100% · รอพี่เลี้ยงประเมินสุดท้ายแล้วใบรับรองจะขึ้นที่นี่</div><a class="btn" href="#apps">ไปดูใบสมัคร</a>`:'ยังไม่มีใบรับรอง · ฝึกงานหรือเรียนคอร์สให้จบก่อน'}</div>`}
  <p class="notice">ป้ายและใบรับรองในเดโมเป็นข้อมูลตัวอย่าง</p>`};
 function needMatch(j){return NEEDS.filter(k=>(j.acc||[]).includes(k)).length}
 V.needs=()=>{const rank=JOBS.filter(j=>needMatch(j)>0).sort((a,b)=>needMatch(b)-needMatch(a)||b.r-a.r);
  return head()+tabs('needs')+`<div class="sec" style="margin-top:0"><h1 style="font-size:1.5rem">ความต้องการในที่ทำงานของฉัน</h1></div>
  <p class="meta" style="margin:-4px 0 10px">เลือกครั้งเดียว Maadoo จะแนะนำงานที่รองรับให้ · ข้อมูลนี้เก็บในเครื่องนี้ และจะไม่ส่งให้บริษัทจนกว่าคุณเลือก</p>
  <div class="box col"><b style="color:var(--ink)">สิ่งที่ฉันต้องการ</b><div class="chips" style="gap:8px">${Object.keys(ACC).map(k=>`<button class="pill" data-need="${k}" aria-pressed="${NEEDS.includes(k)}">${ico(ACCI[k])} ${ACC[k]}</button>`).join('')}</div>
  <label style="display:flex;gap:8px;align-items:center;margin-top:6px"><input type="checkbox" data-needshare ${SHARE?'checked':''}> แจ้งความต้องการเหล่านี้ให้บริษัทตอนกดสมัคร (ปิดไว้ได้)</label>
  <div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn y" data-needuse>ใช้เป็นตัวกรองตอนหางาน</button></div></div>
  <h2 style="font-size:1.05rem;margin-top:16px">งานที่รองรับตามที่เลือก (${rank.length})</h2>
  ${NEEDS.length?(rank.length?rank.map(j=>{const im=(DPH[phKey(j)]||[])[0];return `<a class="needj" href="#job-${j.id}">${im?`<img src="${im}" alt="">`:''}<div style="flex:1;min-width:0"><b>${esc(j.t)}</b><small>${esc(j.co)} · ${esc(j.pay)}</small><div class="chips" style="margin-top:4px">${(j.acc||[]).map(k=>`<span class="chip ${NEEDS.includes(k)?'g':''}">${ACC[k]}</span>`).join('')}</div></div><span class="chip g">ตรง ${needMatch(j)}/${NEEDS.length}</span></a>`}).join(''):'<div class="box empty">ยังไม่มีงานที่รองรับตามที่เลือก</div>'):'<div class="box empty">เลือกอย่างน้อย 1 อย่างด้านบนก่อน</div>'}`};
 function slotShop(){openModal(`<h2 style="font-size:1.2rem">Slot สมัครงานของคุณ</h2><p style="margin:0">ใช้อยู่ ${activeApps()} จาก ${S.slotLimit} Slot · Slot คืนให้เองเมื่อบริษัทตอบหรือคุณถอนใบสมัคร</p>
  <div class="box"><b>ฟรี · 3 Slot</b><div class="meta">ใช้ได้เสมอ ไม่มีค่าใช้จ่าย</div></div>
  <div class="box"><b>Extra Slot ชั่วคราว</b> · ฿39 / 7 วัน<div class="meta">เพิ่ม 1 Slot ช่วงรอผล ไม่ต้องรอ Slot คืน</div><button class="btn y" data-buyslot="1" style="margin-top:6px">เพิ่ม 1 Slot (เดโม)</button></div>
  <div class="box"><b>Plus · 5 Slot</b> · ฿99 / เดือน<div class="meta">สมัครได้พร้อมกัน 5 งาน</div><button class="btn y" data-buyslot="plus" style="margin-top:6px">เลือก Plus (เดโม)</button></div>
  <p class="notice">เดโมนี้ไม่มีการตัดเงินจริง</p><button class="btn" data-close>ปิด</button>`,'Slot สมัครงาน')}
 function sendCert(i){const act=S.apps.map((a,k)=>[a,k]).filter(x=>['wait','invite','booked'].includes(x[0].status));
  if(!act.length){openModal('<h2 style="font-size:1.2rem">ยังไม่มีบริษัทที่สมัครอยู่</h2><p>สมัครงานก่อน แล้วค่อยส่งใบรับรองแนบไปได้</p><button class="btn" data-close>ปิด</button>','ส่งใบรับรอง');return}
  openModal(`<h2 style="font-size:1.2rem">ส่งใบรับรองให้บริษัท</h2><div class="col" id="csl">${act.map(([a,k])=>`<label class="box" style="display:flex;gap:8px;align-items:center"><input type="checkbox" value="${a.job}" checked> ${esc(job(a.job).co)}<small style="color:var(--muted)"> · ${esc(job(a.job).t)}</small></label>`).join('')}</div><div style="display:flex;gap:8px;margin-top:8px"><button class="btn" data-close>ยกเลิก</button><button class="btn y" id="csgo">ส่งใบรับรอง</button></div>`,'ส่งใบรับรอง');
  document.querySelector('#csgo').onclick=()=>{const v=[...document.querySelectorAll('#csl input:checked')].map(x=>+x.value);v.forEach(jb=>SENT.push({job:jb,d:'วันนี้'}));store.set('certsent',SENT);closeModal();toast('ส่งใบรับรองให้ '+v.length+' บริษัทแล้ว (เดโม)');render()}}
 document.addEventListener('click',e=>{const el=e.target;if(!el.closest)return;
  if(el.closest('#bellBtn')){e.stopImmediatePropagation();e.preventDefault();location.hash='notif';return}
  let b;
  if(b=el.closest('[data-nread]')){NR=NL().map(x=>x.id);store.set('nread',NR);render();updBell();return}
  if(b=el.closest('[data-nf]')){NF=b.dataset.nf;render();return}
  if(b=el.closest('[data-nopen]')){if(!NR.includes(b.dataset.nopen)){NR.push(b.dataset.nopen);store.set('nread',NR);updBell()}return}
  if(b=el.closest('[data-bpick]')){BPICK=BPICK===b.dataset.bpick?'':b.dataset.bpick;store.set('badgepick',BPICK);render();return}
  if(b=el.closest('[data-certsend]')){sendCert(+b.dataset.certsend);return}
  if(b=el.closest('[data-need]')){const k=b.dataset.need;NEEDS=NEEDS.includes(k)?NEEDS.filter(x=>x!==k):[...NEEDS,k];store.set('needs',NEEDS);render();return}
  if(el.closest('[data-needuse]')){S.f={...S.f,acc:NEEDS.slice()};location.hash='jobs';toast('ตั้งตัวกรองตามความต้องการของคุณแล้ว');return}
  if(b=el.closest('[data-slotshop]')){slotShop();return}
  if(b=el.closest('[data-buyslot]')){if(b.dataset.buyslot==='plus')S.slotLimit=Math.max(S.slotLimit,5);else S.slotLimit++;store.set('slotlimit',S.slotLimit);closeModal();toast('เพิ่ม Slot แล้ว (เดโม ไม่มีการตัดเงิน)');render();return}
 },true);
 document.addEventListener('change',e=>{if(e.target.matches&&e.target.matches('[data-needshare]')){SHARE=e.target.checked;store.set('needshare',SHARE)}});
 // slot shop entry inside apps page
 const oa2=V.apps;V.apps=()=>oa2().replace(/(<p class="meta" style="margin:8px 0 0">กดรูปบริษัท)/,'<button class="btn" data-slotshop style="margin-top:8px">ต้องการ Slot เพิ่ม?</button>$1');
 const _sc=setCurrent;setCurrent=function(n){_sc(['notif','badges','needs'].includes(n)?'apps':n)};
 const _r=render;render=function(f){_r(f);updBell()};
 const _t=document.title;
 updBell();
})();
